    "anio": 2024,
    "area": "Gestión de la Calidad",
    "resumen": "El informe aborda la implementación y mantenimiento del Sistema de Gestión de Calidad ISO 9001 en la Compañía de Seguros La Positiva, específicamente en el área de siniestros de la Oficina Trujillo. Se detalla la estructura organizacional de La Positiva, fundada en 1937, y su evolución a lo largo de las décadas, incluyendo la expansión en diversas regiones del Perú. El enfoque principal se centra en los procedimientos y estándares aplicados para asegurar la calidad en la atención de siniestros, la actualización de reservas y la documentación necesaria para la gestión de casos de siniestros, como la denuncia policial y el informe médico. La implementación del ISO 9001 en la Oficina Trujillo incluyó la capacitación del personal, la creación de manuales de procedimientos y la adopción de un enfoque sistemático para la mejora continua. Además, se describe el uso de herramientas tecnológicas como el sistema INSUNIX para la gestión de siniestros y la importancia del seguimiento a indicadores de gestión para tomar decisiones informadas. El informe concluye que la implementación del sistema de gestión de calidad no solo ha mejorado la eficiencia operativa, sino que también ha fortalecido l",
