    "area": "Seguridad y Salud Ocupacional",
    "resumen": "La presente investigación tuvo como objetivo principal implementar un plan ergonómico para reducir los riesgos ergonómicos en la empresa Sama Ocupacional, Trujillo 2022; para lo cual, el diseño que se uso fue experimental de categorización pre experimental donde se realizó una pre evaluación y luego una post evaluación una vez implementado el plan ergonómico, la muestra estuvo conformada por 15 trabajadores y para ello se empleó como instrumentos, la Ficha para la identificación y evaluación rápida de riesgos ergonómicos, con los factores de riesgos encontrados se emplea la metodología REBA para posturas y movimientos forzados y el Check List OCRA para movimientos repetitivos. Una vez empleada la metodología REBA para la pre-evaluación se obtuvo como resultado que el 73,33% presenta un nivel de riesgo Medio y el 26,67% presenta un nivel de riesgo Alto; en cuanto la evaluación por la metodología Check List Ocra nos dio como resultado que el 100% presentan un nivel de riego Inaceptable Medio. Posterior a ello, se elaboró y se implementó el plan ergonómico, donde a través de las pausas activas, capacitaciones y rediseños de puestos, se obtuvo el 100% del cumplimiento del plan ergonómi",
