    "resumen": "Esta investigación surge al observar que el proceso de gestión de pago a proveedores de la empresa Quavii se ha visto afectado debido a la cantidad de observaciones referentes al procesamiento de sus documentos de pago, lo que conlleva a reprocesos en las actividades administrativas, sobrecostos por pagos efectuados con demora, incumplimiento de actividades y la posibilidad de asumir multas o demandas. Es por ello, que el presente proyecto de investigación tiene por objetivo aplicar la metodología Lean Six Sigma para mejorar este proceso de la empresa Quavii y así identificar la causa raíz, establecer indicadores, analizar las áreas involucradas y definir nuevas estrategias para optimizar su eficiencia. Para lo cual, se aplicaron las técnicas y herramientas que la metodología Lean Six Sigma ofrece dentro un marco conocido como DMAIC (Definir, Medir, Analizar, Mejorar y Controlar). Entre ellas se encuentran el project charter, la casa de la calidad, diagrama SIPOC, diagrama analítico del proceso, diagrama de flujo, método SMED, auditorías de diagnóstico y de contraste, prueba de hipótesis, gráficas de control, entre otras herramientas. Como resultado de estas mejoras, se obtuvo una ",
