    "resumen": "La idea central del presente trabajo consiste en estudiar la convivencia de dos especies de animales y luego formular un modelo matemático de los fenómenos que se susciten para realizar el presente trabajo; he tenido que utilizar ciertos nociones previas, llamémosle preliminares básicas tales como: nociones de un sistema controlado, criterios de cibernética, algunos criterios de ecología y nociones básicas de algebra lineal, ecuaciones diferenciales básicas, sistemas de ecuaciones diferenciales, criterios elementales de sistemas dinámicos lineales y planos, criterios básicos de estabilidad y conceptos de un modelo matemáticos. Con estos antecedentes, enfoco el tema central en el cual analizo e interpreto algunos modelos maten áticos que simulen el crecimiento o decrecimiento poblacional de especies. Para hacer los análisis uso los métodos inductivo y deductivo, e interpretación con visiones geométricas dinámicas, ecológicas, cibernéticas y con conocimiento de sistemas de control y así conseguir una expresión o modelo matemático que pueda predecir el futuro de las especies en estudio que podría ser útil en la ganadería o agricultura. Al final, informo el deseo alcanzado del trabajo ",
