    "resumen": "El presente estudio se enfoca en análisis de fiabilidad de activos de maquinaria de la empresa SERTMAC SA y como la estadística participa de un rol muy importante en el área de mantenimientos. Utilizando la distribución de Weibull para la fiabilidad se obtuvieron resultados que a nos permite identificar los niveles de criticidad de un activo con ayuda de indicadores MTTR, MTBF y disponibilidad teniendo como principal estudio a la confiabilidad de un tractor para las operaciones en actividades y poder proyectar sus prontos mantenimientos. Este estudio contribuye al campo del mantenimiento en maquinaria no solo agrícola sino a todo lo relacionado en lo que un activo esté involucrado. Las conclusiones del estudio sugieren hacer un análisis estadísticos para el inicio de cualquier investigación para la mejora continua de la flota de activos, haciendo un preámbulo de la importancia de hacer una gestión óptima para generar mejores resultados no solo económico si no en tiempos de operación y mantenimientos, podemos destacar que a través del tiempo un tractor reduce significativamente su confiabilidad si no se aplica lo mencionado en este estudio, hay bastantes procesos para poder encontra",
