    "resumen": "El trabajo de suficiencia profesional presentado se centra en el desarrollo e implementación de una solución tecnológica para mejorar la gestión de reportes de seguridad en las empresas Promigas Perú S.A.C., Gases del Pacífico S.A.C., y Gases del Norte S.A.C. La propuesta consiste en una aplicación móvil desarrollada con Microsoft Power Apps, integrada con Power Automate y SharePoint, con el objetivo de agilizar la comunicación y registro de eventos de seguridad. El proyecto inicia con la identificación de la necesidad de mejorar la gestión en la comunicación de eventos de seguridad. Se desarrolló un plan de proyecto utilizando la metodología PMBOK, que incluyó desde la elaboración de un acta de proyecto hasta finalizar con pruebas de usuario, conformidad de jefatura y publicación para uso de los empleados. La aplicación desarrollada permite a los empleados reportar eventos de seguridad en tiempo real desde sus dispositivos móviles, facilitando la captura de datos, incluyendo imágenes, que se almacenan en SharePoint y se procesan automáticamente mediante Power Automate para su envío por correo electrónico a los responsables. El proyecto demostró que la integración de herramientas d",
