    "anio": 2024,
    "area": "Producción y Operaciones",
    "resumen": "La presente investigación consistió en la simulación secuencial modular de la separación de mezclas azeotrópicas acetona-metanol mediante alternancia de presiones, usando el simulador COCO V.3.7. El procedimiento radicó en seleccionar los componentes y los módulos requeridos consistente en dos columnas de destilación simples, la primera con 52 platos con alimentación fresca óptima en el 37 avo plato operando a una relación de reflujo de 2,34 y presión 101,325 kN/m2 y la segunda con 62 platos, alimentación en el 41 avo con reflujo 3,11 a una presión constante de 405,3 kN/m2 , ambas alimentaciones obtenidas por análisis paramétrico de requerimiento de calor contra plato de alimentación. Asimismo, considerando los requerimientos de calor en el reboiler de17,82 MW para la primera se logró una eficiencia termodinámica de 17,7% y un consumo de calor de 13,19 MW para la segunda, su eficiencia fue de 98,09%. El arreglo topológico en serie permitió la separación de ambos componentes con purezas del 99,4% mol para la acetona y de 99,5% mol para el metanol. Palabras clave: Simulación, mezclas azeotrópicas acetona, metanol, alternancia de presiones, eficiencia termodinámica ABSTRACT The presen",
