    "resumen": "The main objective of this research was to elaborate a proposal for an improvement plan in the fire protection network system in order to reduce the operational risks of the company Casa Grande S.A.A. The first step was to identify and evaluate the main causes of the operational risks existing in the company, then the management of the fire network system of the company was reviewed in detail, and based on this, an improvement proposal was designed in which the fire network system was detailed, considering the current NFPA regulations, and the decreases in the operational risks of the company were evaluated. Finally, a cost-benefit analysis of the proposal was carried out. Among the results it was found that initially, despite the fact that the company has a safety and industrial hygiene area that is in charge of the operational part of the fire protection network system throughout the company, eight of the fourteen areas that have the SRCI have a moderate to important risk level and through an analysis of the SRCI there was a total compliance percentage of 53%, which identifies the need for the improvement proposal in the company's SRCI, the proposal analyzed the improvements of: ",
