    "id": "unt-paper-sciendo-5058-5278",
    "titulo": "Habilidades directivas y Gestión administrativa en funcionarios de las Municipalidades de la Provincia de Sánchez Carrión",
    "autor": "León Luyo, Sandra Lizzette; Mostacero Llerena, Soledad Janet",
    "asesor": "Seijas Velásquez, Segundo",
    "anio": 2023,
    "area": "Logística y Cadena de Suministro",
    "resumen": "La investigación permitió determinar la relación entre las habilidades directivas y la gestión administrativa en funcionarios de las Municipalidades de la Provincia de Sánchez Carrión, 2021. Participaron 25 funcionarios públicos, se empleó el muestreo no probabilístico, a quienes se aplicó el instrumento para medir las habilidades directivas denominado inventario de autoevaluación de competencias profesionales y el instrumento para medir la gestión administrativa, ambos validados y confiables. Los resultados han permitido demostrar que el 64 % de los funcionarios tienen un nivel denominado en proceso en función a las habilidades directivas, seguido de un 16% que presentan un nivel denominado bueno, así mismo un 64 % de los funcionarios consideran que tienen un nivel alto en gestión administrativa y un 36% lo consideró como medio. Concluyéndose que hay una relación directa moderada entre las variables (p-valor<0.05, rs=0.538).",
