    "resumen": "Se propuso como objetivo describir la relación entre comercio electrónico y la calidad de servicio al cliente en la generación Millenial del cercado de Lima, presentando un enfoque mixto, cuantitativo y cualitativo, mencionar también que el tipo de estudio fue teórico, la muestra estuvo constituida por 283 jóvenes de la generación Millenial del cercado de Lima, el método empleado para la resolución de resultados fue hipotético deductivo, utilizando el estadístico Rho de Spearman para estudiar la relación de dependencia entre variables y dimensiones de las mismas, así mismo se utilizó la técnica de encuesta y el instrumento cuestionario para las variables comercio electrónico y calidad de servicio, con una escala de Likert. Se validó el instrumento con la prueba de alfa de Cronbach, mostrando un valor de 0.89 de fiabilidad como resultado, también se utilizó el cálculo de las variables y dimensiones mediante la prueba de normalidad de kolmogorv – Smirnov con significancia 0.00, encontrándose una distribución normal; por ello se realizó el cálculo de la media y rango intercuartílico. Finalmente se determinó que existe relación positiva media entre las variables, comercio electrónico y",
