    "resumen": "El propósito de la investigación es determinar la influencia de la descentralización fiscal en las implicancias y repercusiones económicas y sociales en el Marco Región Ancash-Huánuco-Ucayali, para esto se determinó una muestra no probabilística por conveniencia se eligió 20 especialista sobre el tema, el diseño de investigación fue descriptivo-correlacional, como técnica se utilizó la encuesta y su instrumento el cuestionario, los datos fueron procesados mediante el programa estadístico SPSS versión 26, después del procesamiento de los datos se pudo llegar a los siguientes resultados, la descentralización fiscal afecta de manera importante en el funcionamiento de la economía en la asignación y provisión de bienes públicos locales mejorando la eficiencia en la atención básica sanitaria como son los sistemas educativos, infraestructura que mejora el desarrollo humano, por otro lado se obtuvo como resultado que las implicancias económica y sociales se da en los problemas de transferencias fiscales, dependiente de los recursos vinculados a la renta de explotación de recursos naturales lográndose un chi cuadrado de 0.034 menor que 0.05 lo que significa que existe una incidencia signifi",
