    "id": "unt-paper-sciendo-5227-5413",
    "titulo": "Diseño Generativo para el Centro de I+I+D de la Sede Regional de IMARPE Huanchaco",
    "autor": "Cabel Aguilera, Jhordan Renzzo",
    "asesor": "Arango Retamozo, Solio Marino",
    "anio": 2023,
    "area": "Gestión de Proyectos",
    "resumen": "Esta investigación propone la sistematización de los procesos de diseño evolutivo a través de una metodología aplicada al diseño de la sede descentralizada del Centro de Investigación, Innovación y Desarrollo acuícola y de ciencias oceanográficas del Instituto del Mar del Perú (IMARPE), en la cual se establece una definición del problema arquitectónico, que abarca requerimientos y restricciones, para posteriormente ser traducida en instrucciones de modificación geométrica interpretadas por un algoritmo evolutivo basado en machine learning, obteniendo así como resultado la composición volumétrica del anteproyecto, producto de la evolución de 5000 propuestas diferentes, obtenidas de forma generativa, donde el producto resultante es el mejor posible en base a las restricciones y requerimientos planteados. Este trabajo supone una base de partida para las metodologías de diseño generativo, indaga otras formas de abordar el diseño en la enseñanza de la arquitectura local y explora las posibilidades que brinda la evaluación de múltiples soluciones a un problema en particular.",
