    "area": "Gestión de Proyectos",
    "resumen": "El objetivo de la presente investigación fue determinar la influencia de la gestión de recursos humanos en la productividad laboral en una entidad prestadora de Servicios. El enfoque utilizado fue cuantitativo y la investigación fue de tipo causal explicativo. La población estuvo constituida por un total de 220 colaboradores. La muestra estuvo conformada por la totalidad de la población llegando a ser una muestra poblacional. El tipo de muestreo fue no probabilístico a conveniencia del autor. En la recolección de datos se utilizó el cuestionario. Llegando a concluir que la gestión de recursos humanos influye de manera significativa sobre la productividad con un p valor = 0.001 < 0.05, aceptando la hipótesis alterna de la investigación, este resultado indica que las gestiones que se realicen el recurso humano de la empresa si modifica el resultado de la productividad, en tanto se puede afirmar que la empresa de servicios ha estado gestionando de manera eficiente, por lo tanto a mayor gestión de recursos humanos, mayor nivel de productividad laboral existirá en la empresa.",
