    "titulo": "Modelo de control de gestión financiera para mejorar la rentabilidad de las MYPES sector calzado",
    "autor": "Gómez, Walter; Rodríguez, Ángela",
    "asesor": "Reyes Cruzado, Jorge Luis",
    "anio": 2023,
    "area": "Gestión de Proyectos",
    "resumen": "El objetivo general de esta investigación fue determinar si la gestión financiera guarda una relación significativa con la rentabilidad de las MYPES sector calzado, cuyo tipo de estudio fue no experimental, con diseño correlacional y de corte transversal. Se trabajó con una población de 201 MYPES, obteniendo una muestra aleatoria de 132; se emplearon cuestionarios confiables y validados, así mismo guía de entrevista, procesando los datos a través del SPSS. Se utilizó el coeficiente de correlación de Spearman para evaluar la relación entre las variables de interés con una significancia de 5%. Se identificó que el 64% de las MYPES si conoce en detalle el balance general, el 26% si manejan un plan de inversión, el 71% saben con claridad la rentabilidad que genera su empresa, el 39% cuenta con un flujo de caja proyectado. Finalmente, se encontró una correlación de 0.786 (p-sig= 0.039) entre el control de la gestión financiera y la rentabilidad concluyéndose que existe una relación positiva fuerte.",
