    "area": "Gestión de Proyectos",
    "resumen": "El objetivo del presente estudio es determinar por qué el uso del cuerpo del imputado como fuente de prueba, afecta el debido proceso en el distrito judicial de Cajamarca, 2017 - 2019. Metodología, se utilizó el enfoque cuantitativo y la investigación fue de tipo básica de alcance descriptivo. La población estuvo constituida por jueces del ya mencionado distrito judicial. Mientras que, la muestra estuvo conformada por 20 jueces especializados en materia penal. La selección de ésta se realizó mediante muestreo no probabilístico, aplicando el criterio intencional del investigador. En el recojo de la información se aplicó la técnica de la encuesta y el cuestionario como instrumento. Los resultados demuestran que, el 40% de los magistrados afirmaron que se requiere el consentimiento del imputado para el uso del cuerpo como fuente de información probatoria y el 10% corroboró que, siempre se vulnera el debido proceso. Concluyéndose en caso de que en el cuerpo del imputado existan muestras imprescindibles para brindar eficacia probatoria a la información que abastece la escena del evento delictivo, cuerpo de la víctima o testigos, al estar vedada la dinámica inquisitiva; la intervención c",
