    "resumen": "La Gestión de cartera de inversión renta variable, se fundamenta en el comportamiento racional del inversionista minimizando riesgo y maximizando rentabilidad, bondades ofrecidas por la Teoría de Portafolios de Markowitz (en adelante TPM). El objetivo fue Gestionar la Cartera de Inversión Renta Variable aplicando la TPM, para determinar a partir de ésta, si una cartera de activos financieros que se negocian en Standard y Poor´s 500 (SyP 500) atiende el principio de maximizar la rentabilidad del inversor, considerando la mínima varianza. La población estuvo constituida por las 505 empresas que componen los 11 principales sectores económicos del índice SyP500, se utilizaron filtros de análisis fundamental para obtener la muestra y se identificaron 34 empresas de los principales sectores económicos del índice SyP 500 a las que se les aplicó la TPM para gestionar una cartera de inversión en renta variable y se utilizaron las herramientas financieras Finviz, Yahoo Finance, Select Sector, apoyados en Microsoft Excel. El diseño de la investigación fue pre-experimental con enfoque cuantitativo – cualitativo. Una de las conclusiones fue que la Gestión de Cartera de Inversión en Renta Variab",
