    "titulo": "Competencias gerenciales y su influencia en la efectividad administrativa de la Gerencia Regional de Salud La Libertad",
    "autor": "Zavaleta, Monique",
    "asesor": "Ruiz Sirlopu, José Ronald",
    "anio": 2023,
    "area": "Producción y Operaciones",
    "resumen": "El objetivo del estudio fue determinar la influencia de las competencias gerenciales en la efectividad administrativa de la Gerencia Regional de Salud de La Libertad en el año 2022. Para lograrlo, se utilizó un enfoque cuantitativo de tipo aplicado, con un diseño no experimental transversal y nivel correlacional. Se seleccionó una muestra de 169 colaboradores de una población total de 300 en la Gerencia Regional de Salud de La Libertad. A estos colaboradores se les administraron dos encuestas, las cuales fueron validadas mediante juicio de expertos y la prueba del coeficiente alfa de Cronbach. Los resultados revelaron que las competencias gerenciales presentaron un nivel de deficiencia del 48.8%, mientras que la efectividad administrativa alcanzó un 49.4%. Se pudo concluir que existe una relación directa de magnitud grande (0.50 ≤ rs = 0.91 ≤ 1.0) entre las competencias gerenciales y la efectividad administrativa. Esto evidencia que un 83% de la variabilidad en la efectividad administrativa se debe a las competencias gerenciales de los colaboradores en la Gerencia Regional de Salud de La Libertad en el año 2022.",
    "palabrasClave": [
      "Competencias gerenciales",
      "efectividad administrativa",
      "personal administrativo"
    ],
