    "titulo": "Factores determinantes en la estructura de capital de las empresas mineras registradas en la Bolsa de Valores de Lima, periodo 2013-2022",
    "autor": "Agreda Timoteo, Elizabeth Lisset Zoe; Quilia Valerio, Jhoansson Victor Manuel",
    "asesor": "Hernández Molina, Ángel",
    "anio": 2023,
    "area": "Gestión de Proyectos",
    "resumen": "El propósito principal de esta investigación fue identificar los elementos que influyen en la composición financiera de las compañías mineras registradas en la Bolsa de Valores de Lima durante el periodo de 2013 a 2022. El enfoque metodológico utilizado fue cuantitativo, aplicado, de diseño no experimental y longitudinal. La población analizada consistió en 30 empresas mineras cotizadas en la bolsa, abarcando 10 periodos entre los años mencionados. Se emplearon dos estados financieros, y se diseñó una guía de análisis documental como herramienta para establecer los criterios de medición basados en los indicadores. Los datos financieros se recopilaron de la página web de la Bolsa de Valores de Lima (BVL). Los resultados obtenidos indicaron una alta y significativa correlación entre la estructura financiera y los factores determinantes, tales como la rentabilidad del patrimonio, la tangibilidad de los activos, el crecimiento de la empresa, la liquidez y el riesgo del negocio. En conclusión, se determinó que estos factores determinantes afectan directamente el nivel de endeudamiento de las empresas mineras, lo que implica que cualquier variación en dichos factores generará una reacció",
