    "id": "unt-paper-sciendo-5580-5663",
    "titulo": "Gasto público y su incidencia en la calidad de vida de la población del distrito de Pacasmayo- 2019-2022",
    "autor": "Popayán, Mery",
    "asesor": "Baca López, Marcos Gregorio",
    "anio": 2023,
    "area": "Gestión de la Calidad",
    "resumen": "Esta investigación se realizó con finalidad de identificar la incidencia del gasto público en Municipalidad Distrital Pacasmayo, durante 2019-2022, en bienestar de su población; asimismo, evaluar presupuesto, y su ejecución, establecer el nivel de influencia del gasto, proponiendo estrategias de mejora. El método fue inductivo-deductivo, descriptivo, correlacional, observacional, longitudinal, y mixto; empleándose encuesta, evaluación presupuestaria, estadística descriptiva e inferencial. La muestra fueron 39 funcionarios ediles. Se procesó la data con MS Excel; a partir Pearson se analizó la asociación de factores, a 0,05 de significación. Los hallazgos fueron: gasto eficiente (85,02%); gasto social, 61,61%; gasto en servicios básicos, 82,48%; en salud, 2,44%; en educación, 26,18%; en canales de regadío, 7%; en conectividad, 62,85%; inversión en programas sociales, mínima (0,40%), por parte de la comuna; bienestar, 19,32%. Se obtuvo alta correlación (R=0,9288), muy significativa (p<0,01), entre el gasto público municipal distrital de Pacasmayo y el nivel de vida de su población, del mismo modo, una considerable asociación (R=0,6970), significativa (p = 0,011<0,05), en cuanto a la ",
