    "id": "unt-paper-sciendo-5662-5717",
    "titulo": "Prácticas familiares en el cuidado del niño con asma bronquial en pandemia por COVID-19",
    "autor": "Goicochea Mori, Daisy Rosmary; Chunga Medina, Janet Julia",
    "asesor": "Seijas Velásquez, Segundo",
    "anio": 2023,
    "area": "Producción y Operaciones",
    "resumen": "La investigación tuvo como propósito el análisis acerca de cómo son las prácticas familiares en el cuidado del niño con asma bronquial en pandemia por COVID-19 del Centro de Salud San Martin de Porres. La recolección de la información se realizó a través de la entrevista en profundidad siendo seleccionados ocho familiares por criterio ético y saturación teórica del discurso. Del análisis del discurso emergieron tres categorías , cada una organizadas en subcategorías : a) Adaptación en el comportamiento cuidativo para conservar la salud con subcategorías como: Afrontamiento del entorno familiar - Mantenimiento y compromiso familiar, b) Modificación al estilo de vida familiar frente al cuidado del niño con asma bronquial, expresada en las subcategorías: Formación de hábitos - Disposición para la protección evitando el contagio y por último c) Fortalecimiento para mantener el cuidado en pandemia por COVID-19 plasmada en Actividades de contingencia por COVID-19 y Aislamiento Familiar. El análisis de la información muestra de qué manera una dinámica interaccional y comunicativa prolongada en el hogar consolida las prácticas de cuidado, especialmente en lo que se refiere a familias más e",
