    "area": "Producción y Operaciones",
    "resumen": "Currently, the search for eco-friendly products has become more intensive, guiding the agro-industry towards more sustainable practices. Obtaining bioactive compounds with antifungal activity represents a viable source of fungicides for postharvest use, since up to now there is still a high demand for chemical fungicides in the industry. The effect of two aqueous extracts of acetone origin obtained from blueberry branches and leaves (mixture) and avocado seed was evaluated. This plant material is part of agro-industrial waste from the production process of the company Camposol S.A. To determine the concentration of polyphenols, the Folin Ciocalteu method was used and for the antioxidant capacity, the DPPH radical method. The tentative identification of compounds present in each extract was performed using UHPLC-DAD-ESI/MS. The acetone extracts were dried and re-suspended in water. Three concentrations (5, 25 and 50 mg/mL) were used on the inhibition of spore germination and mycelial growth of Botrytis sp. 55% inhibition of spores was obtained after 24 h of incubation and 19% inhibition in growth mycelial at 7 days of incubation. This research contributes to the valorization of by-p",
