    "id": "unt-paper-sciendo-4283-4757",
    "titulo": "Gestión de cuentas por cobrar y su efecto en la liquidez en una empresa de transportes de Trujillo",
    "autor": "Villavicencio Zare, Yesenia; Soto Abanto, Segundo Eloy",
    "asesor": "Seijas Velásquez, Segundo",
    "anio": 2022,
    "area": "Logística y Cadena de Suministro",
    "resumen": "El presente artículo tiene como objetivo determinar el efecto de la gestión de cuentas por cobrar en la liquidez en una empresa de transportes de Trujillo. La metodología es de diseño no experimental de corte transversal bajo el enfoque cuantitativo con un alcance descriptivo. La técnica utilizada fue documental para analizar cada variable en los periodos 2015 - 2019 de la empresa en estudio. Entre los principales resultados se encontró que, la empresa realiza una deficiente gestión de sus cuentas por cobrar ello se muestra en los 198 días de periodos de cobro por el servicio de carga y la disminución de su rotación de cuentas en 1.8 veces, en cuanto a su liquidez al año 2019 su ratio de liquidez corriente fue de 0.77, la liquidez absoluta fue de 0.39, su prueba ácida fue de 0.72, y el capital de trabajo fue de -1,728,703.00 por lo que su activo corriente no fue capaz de cubrir sus pasivos a corto plazo, llegando a la conclusión que la gestión de cuentas por cobrar tiene efecto negativo en la liquidez de la empresa.",
    "palabrasClave": [
      "Logística y Cadena de Suministro",
      "Ingeniería Industrial",
      "UNT"
    ],
