    "autor": "Céspedes, Tania",
    "asesor": "Ruiz Sirlopu, José Ronald",
    "anio": 2022,
    "area": "Gestión de la Calidad",
    "resumen": "El presente estudio se realizó en la provincia de Virú durante el año 2013, con la finalidad de determinar el impacto de la ejecución del presupuesto de la Municipalidad Provincial en la calidad de vida de su población; asimismo, analizar el nivel de ejecución presupuestal, e identificar cómo la ejecución presupuestal influyó en la calidad de vida. El método de investigación implementado fue el inductivo-deductivo, descriptivo, analítico, observacional, de corte transversal, cualitativo y cuantitativo. Se aplicaron 367 encuestas a pobladores y, 36, a funcionarios de la municipalidad provincial; procesándose en MS Excel, para determinar la media, desviación estándar y coeficiente de variación; asimismo, los estadísticos de prueba de contrastación de las variables en estudio. El nivel de ejecución del gasto fue suficiente (98%); la eficiencia del gasto social ha sido del 75,52%, refiriéndose a inversiones en servicios básicos, salud, educación, y bienestar en general; la eficiencia del gasto fue 19% superior. Existe una correlación significativa (0,62) entre la ejecución presupuestal municipal provincial, durante el año 2013, y el nivel de vida de su población. Se concluye que, la ej",
