    "titulo": "Factores determinantes de la cultura museológica en la ciudad de Trujillo",
    "autor": "Vega Llerena, Humberto Manuel; Lopez Rodriguez, Nancy Isela",
    "asesor": "Hernández Molina, Ángel",
    "anio": 2022,
    "area": "Gestión de la Calidad",
    "resumen": "La investigación tuvo como objetivo describir los factores determinantes de la cultura museológica en la ciudad de Trujillo, a partir de la presencia del Estado en la promoción de políticas culturales, alentando por otra parte el crecimiento de una economía capitalista, en beneficio de la expansión de estructuras de concreto armado, conformando las urbanizaciones de la ciudad y trastocando el uso de tierras agrícolas, para atender el acelerado crecimiento demográfico. La investigación se desarrolla a partir de dos técnicas fundamentales, el análisis documental y la encuesta. Uno de los hallazgos de mayor relevancia es que la cultura museológica de la ciudad de Trujillo es débil, debido a que muchas veces la idiosincrasia de la población citadina conlleva a interesarse por conocer los museos foráneos, en detrimento de los museos locales; además la falta de una política de mejora de la calidad en la gestión posibilitaría una débil investigación museológica que no permitiría plenamente la participación e interacción ciudadana en la identificación con su patrimonio y el fortalecimiento de la ciudadanía.",
    "palabrasClave": [
      "cultura museológica",
      "política cultural",
      "identidad",
      "museo universitario"
    ],
