    "id": "unt-paper-agroindscience-4359-4804",
    "titulo": "Influence of temperature on the rheological behavior of industrialized honey",
    "autor": "Rodriguez-Navarro, Haydee; Vivanco-Pezantes, David",
    "asesor": "Buchelli Perales, Orivel Jackson",
    "anio": 2022,
    "area": "Producción y Operaciones",
    "resumen": "In the present work, the effect of temperature on the rheological properties of the industrialized honey of three different high-trade brands in the northern, central and southern Lima markets was studied. The physicochemical characteristics of water activity, specific gravity, moisture content, brix degrees, refractive index and pH were analyzed. No significant difference was found between the values ​​of the physicochemical properties within and between the groups of the commercial brands analyzed (p> 0.05). The industrialized honey was tested with a Brookfield RVDV-E concentric viscometer using a flat disk spindle at five temperature levels from 20 ºC to 60 ºC, and the influence of temperature with dynamic or absolute viscosity was studied. Through the rheogram, a behavior of a Newtonian fluid was observed. For all samples it was found that the mean absolute viscosity decreases with temperature at 20 ºC (7430 mPa∙s), 30 ºC (2636 mPa∙s), 40 ºC (955 mPa∙s), 50 ºC (440 mPa∙s) and 60 ºC (267 mPa∙s). The dependence of the viscosity with the temperature was described by a mathematical exponential model of three constants proposed in this investigation that gave a good fit, obtaining a",
