    "area": "Producción y Operaciones",
    "resumen": "Golden gooseberry (Physalis peruviana) and tree tomato (Solanum betaceum) have bioactive components, which open up the possibility of finding new ways to industrialize them. The objective of the study was to report the chemical and sensory characterization of a new alcoholic beverage produced by mixtures of Physalis peruviana and Solanum betaceum fruits, through fermentation with Saccharomyces cerevisiae (Ale) and Saccharomyces pastorianus (Lager). The physicochemical characterization of the beverages obtained was determined by basic parameters such as alcoholic degree, pH, density, total soluble solids, which were analyzed using: the AOAC \"Official Methods of Analysis\". Total carotenoids were analyzed according to: mg b-carotene eq/100g; the total phenolic compounds were determined under the Folin Ciocalteus protocol; the color characteristics (L*, a* and b*) using computer vision and Python data analysis. The sensory characterization was established with the help of 60 panelists, who evaluated 8 characteristics (flower aroma, nut aroma, wood aroma, astringency, body, flower odor, nut odor, and wood odor). Through a principal component analysis (PCA) and clustering analysis, it wa",
