    "resumen": "La importancia de la productividad del empleado público en el desarrollo del país es un tema muy presente del ámbito de la gestión pública, la cual se ve sometida a distintas condiciones laborales según el sistema de trabajo al que se esté vinculado, y siendo motivo del presente estudio que se centra en dos regímenes laborales en las Municipalidades de San Agustín de Cajas y Pilcomayo, Provincia de Junín. El objetivo fue determinar la diferencia en la productividad del empleado público del Decreto Legislativo 276 y CAS 1057 de las municipalidades indicadas. Metodológicamente, el diseño de investigación es aplicado, descriptivo con enfoque cuantitativo y transversal. La población y muestra estaba compuesta por 120 trabajadores de las municipalidades. Como técnica se empleó la encuesta y la observación y para la validación de los instrumentos se utilizó el método de validez de contenido a través del juicio de expertos; el estudio de los datos se realizó mediante el empleo de análisis descriptivo, empleando el programa estadístico SPSS 24. Se concluyó que no existe diferencia significativa en la productividad del empleado público del Decreto Legislativo 276 y CAS 1057 de las Municipal",
