    "resumen": "El estudio tiene como objetivo encontrar la relación entre la calidad de servicio y la satisfacción de los clientes de una institución financiera pública de una región del norte del país. Su importancia radica en encontrar dicha relación entre la calidad y satisfacción. El fin fue analizar la relación de la calidad de servicio y la satisfacción de los clientes en una agencia del Banco de la Nación al norte del Perú. La población compuesta por 4200 clientes y una muestra de 352. Se utilizó la técnica cuantitativa de la encuesta y como instrumento el cuestionario. Las confiablidades fueron de 0,973 y 0,981. Para analizar y procesar la información se hizo uso del programa Excel. Se concluyó que el nivel de significancia del “p” valor de Chi-cuadrado es 0,003, que establece que la calidad de servicio tiene una relación directa en la satisfacción de los clientes del Banco de la Nación, registrando un nivel medio alto de calidad de servicio y una satisfacción de los clientes nivel medio.",
