    "resumen": "El artículo versa sobre la adaptación de comportamientos de alumnos en relación a la procedencia en un centro de estudios en la ciudad de Trujillo, Perú El objetivo fue determinar si existen diferencias significativas entre los niveles de adaptación de conducta de los alumnos foráneos y lugareños de un centro de estudios pre-universitario de la Universidad César Vallejo, en Trujillo. Investigación de carácter básica y descriptiva de dos grupos y transversal. La población y muestra compuesta por estudiantes en número de 133. Como instrumento se empleó el inventario de adaptación de la conducta conformado por 123 preguntas y validado con fórmula de Spearman-Brown y con confiablidad de Alfa de Cronbach. Para analizar la información se utilizó la estadística descriptiva con tablas de doble entrada y la estadística analítica que establecía diferencia entre medias, además se utilizó el programa Excel, versión SP2. Se concluyó que existía una relación muy significativa de dependencia entre la procedencia (foráneo o lugareño) y el nivel de adaptación general en los estudiantes del centro pre-universitario. (chi cuadrado: 16,227), lo cual implica una atención diferenciada entre alumnos forá",
