    "id": "unt-paper-sciendo-3994-4528",
    "titulo": "Gerente Cognoscente: Combinación de gerentes coach y científico para liderar la gestión moderna",
    "autor": "Recuenco Cabrera, Aurelio Daniel",
    "asesor": "Castillo Chung, Aldo Roger",
    "anio": 2021,
    "area": "Gestión de Proyectos",
    "resumen": "El presente artículo tiene como objetivo principal presentar un nuevo modelo de gerente acorde con las competencias gerenciales actuales exigidas por los continuos cambios producidos en el desarrollo de las actividades organizacionales en relación a los estilos de vida a los que son sometidas las sociedades por la presencia cada vez más intensa de nuevas formas de pensar, interpretación, innovación, tecnología, etc. Esto y mucho más, hace que hoy en día se requieran gerentes más competentes no sólo en el aspecto intelectual, sino en otros aspectos para que así les sea más fácil gestionar y tomar decisiones. Es así, que se propone el nuevo modelo directivo gerencial denominado gerente cognoscente que es el resultado de la combinación de dos tipos de gerente que en los últimos tiempos están teniendo acogida en los procesos directivos organizacionales y que buscan la incorporación del coaching y la investigación a los procesos de gestión, sumados a otros ya existentes. Este gerente cognoscente es la reunión de las competencias que corresponde al gerente coach y gerente científico y que determina un nuevo concepto más global de percepción, interpretación y aplicación en todo sentido ge",
