    "anio": 2021,
    "area": "Gestión de la Calidad",
    "resumen": "El objetivo de la investigación fue evaluar la sustentabilidad de los agroecosistemas cafetaleros conducidos por los agricultores familiares del distrito de Vitoc, Región Junín. Se eligieron seis localidades del distrito y dentro de cada localidad, en forma proporcional, las propiedades de los agricultores familiares. Se evaluaron las dimensiones económicas (rentabilidad, ingreso neto mensual y riesgo económico), ambiental (conservación de la vida del suelo, riego de erosión y manejo de biodiversidad) y social (satisfacción de las necesidades básicas, integración social y conciencia ecológica) y el Índice de Sustentabilidad General. Asimismo, para considerar que el agroecosistema es sustentable, se consideró que el indicador debe ser mayor a 2 en todas las dimensiones y en el índice general. Los resultados muestran que los indicadores obtenidos para las dimensiones económica, ambiental, social y el índice general son favorables y orientan hacia una agricultura sustentable. Sin embargo, presenta problemas con la diversificación de los cultivos para la venta, protección del suelo y la cobertura sanitaria, las que pueden ser considerados como una debilidad del agroecosistema. Se concl",
