    "id": "unt-paper-agroindscience-3447-4122",
    "titulo": "Efecto del poliacrilato de sodio (PANa) en la supervivencia e incremento dasométrico de dos especies forestales durante dos años en campo",
    "autor": "Bernaola-Paucar, Rosario M.; Zanabria Cáceres, Ysaías",
    "asesor": "Seijas Velásquez, Segundo",
    "anio": 2021,
    "area": "Gestión de la Calidad",
    "resumen": "La problemática del uso de suelos de aptitud forestal en las regiones áridas y semiáridas presenta escasez de lluvias y baja calidad de suelos, por ello, es importante buscar alternativas que permitan superar estos inconvenientes. El presente tiene como objetivo evaluar el efecto del Poliacrilato de Sodio (PANa) de pañales desechables usados en la supervivencia y crecimiento dasométrico de dos especies forestales, durante dos años en campo. Para lo cual se establecieron plantaciones de Pinus radiata D. Don y Polylepis incana bajo tres tratamientos de Poliacrilato de sodio, se evaluó el incremento dasométrico y el porcentaje de supervivencia cada seis meses durante dos años. Para el análisis de las variables se utilizó el diseño estadístico multifactorial. Los resultados indican que el mayor incremento de la altura y diámetro se dio en ambas especies forestales que fueron reforestadas bajo el tratamiento 2 y tratamiento 3, el mayor porcentaje de supervivencia en P. radiata se presentó en el tratamiento B, mientras que en P. incana el testigo presento el mayor porcentaje de supervivencia.",
