    "anio": 2021,
    "area": "Producción y Operaciones",
    "resumen": "En los últimos años, ha habido un creciente interés por la biomasa como alternativa a los combustibles fósiles, la digestión anaeróbica (DA), está fuertemente motivada por este marco porque es uno de los métodos más idóneos para el aprovechamiento energético, en la producción de energía renovable en forma de biogás rico en metano (CH4); en el proceso biológico de la generación de metano se distinguen tres etapas: Hidrólisis, Acidogénesis y Metanogénesis, en las que actuan diferentes microrganismos. Para mejorar el proceso de producción de biogás, existen algunos procedimientos como: Uso de catalizadores, Dosificación de mezclas mediante la relación C/N, Agitación del sustrato y control del pH, Uso de zeolita natural y Calentamiento de la cámara de fermentación con energía solar; mediante estos métodos podemos mejorar el rendimiento del biogás, los mismos que incrementan la masa del gas metano, niveles de temperatura y pH óptimos, para el crecimiento y reproducción bacteriana adecuada. Por otra parte, los dispositivos utilizados en la digestion anaerobia son Reactores de mezcla completa sin recirculación, Reactores de mezcla completa con recirculación, Reactores con retención de bio",
