    "titulo": "Aplicación de las herramientas de la ingeniería de métodos en el cultivo de arroz para incrementar la rentabilidad en las empresas agrícolas del Valle Jequetepeque",
    "autor": "Cabanillas Tejada, Jersonn; León Ríos, Jampier José Gabriel",
