    "anio": 2020,
    "area": "Gestión de Proyectos",
    "resumen": "The objective of this project is to diagnose, study, formulate and implement method engineering in rice cultivation in a sample of agricultural companies in the Jequetepeque Valley to increase profitability, with funding from the National Institution of Agricultural Innovation through the National Program of Agrarian Innovation, being key piece the volume of the hydric resource that is used for all the process of this crop, to reduce and to save its consumption. In the first instance through interviews and the observation of the cultivation of other plots, it is possible to identify the main problems and difficulties for both the farmer and the worker, which was used to draw up an Ishikawa diagram, as well as to define the detailed of activities of the whole process rice cultivation, in the stages of preparation of land and nursery, the activities are shared receiving the same treatment for both plots that will be treated until the transplant in final the field where from that moment they will be carried out under different methods of irrigation : the traditional method of irrigation of constant sheets of water and the method of irrigation of intermittent dry. In both methodologies",
