    "id": "unt-paper-agroindscience-2855-3249",
    "titulo": "Compatibilidad de multipatrón / yema y resistencia a antracnosis de guanábana (Annona muricata L.)",
    "autor": "Marmolejo, Doris; López, Glicerio",
    "asesor": "Arango Retamozo, Solio Marino",
    "anio": 2020,
    "area": "Producción y Operaciones",
    "resumen": "Teniendo como objetivo determinar la compatibilidad de multipatrón / yema y evaluar incidencia y severidad de la antracnosis en guanábana, a nivel de vivero, se realizó la investigación en Chanchamayo, Junín. Iniciándose con la colecta de semilla de ecotipos de Annona squamosa (anona) y Annona muricata (Blanca, Amarilla, y Negra), para generar el multipatrón. Las yemas fueron extraídas de plantas madres seleccionadas provenientes de campos en producción. Se realizaron 17 injertaciones diferentes de multipatrón-yema con el método púa central en condiciones de invernadero, siendo evaluada su compatibilidad bajo el diseño BCR. Se registraron variables de porcentaje de germinación, compatibilidad multipatrón/yema y severidad de antracnosis mediante escala Logarítmica Diagramática. Los resultados determinaron que la germinación de semilla de los ecotipos Blanca (T1) y Amarılla (T4) fue de 100% y negra (T7) 74%. La injertación de patrón Blanca con yema Indalsa-063 presentó 94% de compatibilidad, generando plantas clónales BI01008; el patrón Negro con yema Indalsa-130 con 91% de compatibilidad generando plantas clónales NI02010; las otras injertaciones tuvieron valores menores del 89%, ob",
