    "titulo": "Análisis de segregación, obtención de semilla de maca (Lepidium meyenii) en segunda selección y producción en dos altitudes",
    "autor": "Villaorduña-Caldas, Leonidas F.; Zevallos-Arias, Edith L.",
    "asesor": "Buchelli Perales, Orivel Jackson",
    "anio": 2020,
    "area": "Gestión de Proyectos",
    "resumen": "Los trabajos agronómicos para la obtención de semillas homogéneas de seis morfotipos de maca (Lepidium meyenii) en estudio en su segunda generación, utilizando el método de la selección individual; así como una aproximación de los costos de producción en las dos fases del cultivo para el cálculo de su rentabilidad económica, tuvieron lugar en la Provincia de Pasco, durante los años 2018 y 2019. Los resultados indican que aún no se ha podido determinar los fundamentos científicos y/o técnicos que dan coloración a los hipocotilos de maca; es decir, aún no se puede afirmar científicamente que los colores homogéneos de los hipocotilos buscados se debe a razones genéticas o a las condiciones ambientales y/o a los tipos de suelos. Los morfotipos en investigación son: negro, blanco, rojo, amarillo, plomo y rosado. La productividad de maca por unidad de superficie cultivada en su hábitat natural sobre los de 4000 msnm, es 50 por ciento más respecto a la productividad lograda a una altitud de 3300 msnm. Con los análisis de costos y productividad, se encontró que la producción de hipocotilos frescos no debe ser inferior a 4400 kilogramos por hectárea para evitar pérdidas económicas al agricu",
