    "id": "unt-paper-agroindscience-2974-3302",
    "titulo": "Efecto acaricida de aceite esencial de molle (Schinus molle) en el control de Varroa destructor en colmenas de abejas (Apis mellifera)",
    "autor": "Huamán, Norma; Silva, Guadalupe",
    "asesor": "Olivares Espino, Iván Martín",
    "anio": 2020,
    "area": "Gestión de Proyectos",
    "resumen": "Varroa destructor es un ácaro, considerado el más peligroso que causa graves daños en colmenas de Apis mellifera, como la disminución significativa o muerte total de su población. El uso de aceites esenciales es considerado una alternativa para controlar la población de ácaros en colmenas. El efecto acaricida del aceite esencial obtenido de Schinus molle se evaluó en colmenas infestadas. El aceite esencial de molle fue extraído a partir de frutos maduros recolectados en la región Apurímac, mediante la técnica de arrastre de vapor. La composición del aceite esencial se caracterizó mediante cromatografía de gases-espectrometría de masas (GC-MS). El aceite de Schinus molle está compuesto por hidrocarburos monoterpénicos, como el α-phellandrene (33,04%), el β-myrcene (16,11%) y el D-limonene (16,55%). Se prepararon siete tratamientos (aceite esencial + Tween 80 en concentraciones de 5; 10; 15; 25; 50; 75 y 100%, respectivamente), y fueron comparados con el tratamiento control (acaricida comercial, Sanitraz® al 12,5%). Después de 24 horas el tratamiento con 15% aceite esencial y Tween 80, fue el que obtuvo mayor efecto acaricida comparado a los demás tratamientos. El aceite esencial de ",
