    "id": "unt-paper-agroindscience-2980-3310",
    "titulo": "Efecto del guano de isla en el rendimiento de dos variedades de Quinua (Chenopodium quinoa Willd) en suelo degradado",
    "autor": "Cosme, R.C.; Reynoso, A.F.",
    "asesor": "Benites Gutiérrez, Miguel Armando",
    "anio": 2020,
    "area": "Producción y Operaciones",
    "resumen": "El objetivo del presente trabajo de investigación fue evaluar el efecto del Guano de las Islas en el rendimiento de dos variedades de quinua (Chenopodium quinoa Willd) en suelo en proceso de degradación y suelo de alta fertilidad natural, para ambas condiciones de suelo se empleó el diseño experimental de bloques completos al azar, con seis tratamientos y tres repeticiones, la dosis de abonamiento para cada tipo de suelo se homogenizó de acuerdo a los resultados de análisis de suelos. Se evaluaron siete variables (altura de la planta, longitud de panoja, diámetro de panoja, diámetro de tallo, diámetro de grano, peso de mil granos y granos por planta). Los resultados mostraron que la aplicación de guano de isla (2110 kg*ha-1), 75% a la siembra y 25% al aporque (etapa de ramificación), en suelo en proceso de degradación, obtuvo los mayores valores, la variedad INIA-433, en cuanto a altura de planta (157 cm), peso de mil granos (2,39 g) y rendimiento (4 232,14 kg/ha), estos valores están muy por encima de los obtenidos por los tratamientos que no fueron fertilizados con guano de isla. Se concluye que el abono orgánico (guano de isla) influye positivamente en el rendimiento.",
