    "area": "Gestión de la Calidad",
    "resumen": "Se evaluó cinco poblaciones de la variedad Blanco del Cusco perteneciente a la raza Cuzco Gigante de maíz en el valle del Mantaro – Huancayo - Perú. Las poblaciones son resultado de procesos de introducción y adaptación de germoplasma al valle del Mantaro. Los experimentos fueron conducidos en tres localidades durante el período 2020. Las mejores poblaciones para rendimiento de grano fueron Chingas, Hualhuas, Blanco Quispicanchi e INIA - Blanco Urubamba, con rendimientos de 6,18; 6,10; 5,92 y 5,75 t/ha-1, siendo superiores a Chongos, más precoz, de menor altura de planta y mazorca que obtuvo un promedio de 5,18 t/ha-1. La floración masculina como femenina son indicadores de precocidad de las poblaciones, siendo los más precoces Chongos, INIA- Blanco Urubamba y Chingas con promedios menores en días a la floración femenina y considerándose semi-tardíos Blanco Quispicanchi y Hualhuas. Las poblaciones de menor altura de planta fueron el Chongos y el INIA -Blanco Urubamba con promedios de 235 y 243 centímetros, asimismo para altura de mazorca con promedios de 120 y 128 centímetros respectivamente. El estudio permitió determinar las diferencias en rendimiento y características de planta ",
