    "area": "Logística y Cadena de Suministro",
    "resumen": "El objetivo principal del presente trabajo fue elaborar la propuesta de implementación de un plan de gestión ambiental basado en la norma ISO 14001:2015 para un centro piloto de panificación. La metodología aplicada consta de 3 etapas: diagnóstico actual del centro productivo mediante inspecciones, identificación de procesos y actividades propios del centro piloto, evaluación de matriz de aspecto ambientales y por último la propuesta del plan de gestión ambiental. Durante la recolección de datos se evidenció algunas oportunidades de mejora con respecto al tema de residuos sólidos, lo mismo para con el uso de recursos indispensables para las actividades del centro piloto, permitiendo plantear propuestas para mitigar posibles impactos ambientales. Finalmente, el resultado de la evaluación concluye que los aspectos ambientales que podrían generar impactos significativos son: la falta de control de consumo de recursos (agua y luz), y problemática en la disposición y almacenamiento de residuos sólidos (falta manual de Gestión de Residuos Sólidos y falta de un almacén Temporal de Residuos Sólidos). El plan de gestión ambiental propuesto pretende disminuir el impacto ambiental del centro ",
