    "resumen": "The purpose of this research is to demonstrate the economic growth of a company dedicated to the production and marketing of fresh asparagus, in the department of La Libertad, through exports to the Japanese market. For the present project we have used the type of applied - descriptive research and the theoretical research method for which we have used historical price information. For the present study we have used the type of applied - descriptive research and the theoretical research method, used historical information. The project started with the strategic planning of the company, which determined the strategies to follow for the sales increase pursued by the project, continuing with the investigation of the Japanese market and the profile of the consumer. In the technical study phase the current situation of the company, the production process, the logistics chain, the quality control, location and size of the plant were contemplated. Later in the project's engineering, the price analysis was carried out, dating from exports to the Japanese market of the main suppliers of fresh asparagus; In order to determine the projection of unmet demand considering revenues and expenditur",
