    "resumen": "Abstract The purpose of this research was to deploy a process optimization system, according to the run to target methodology, in the company Stevia One Perú SAC. For the execution of this investigation the design type of the research was diagnostic since it was inclined towards the evaluation of the root cause of the problem within the company Stevia One Perú SAC. starting with a fieldwork in which the facilities and the different processes were observed, the purpose was to show the most potential risks in the company in order to optimize and improve them. This process optimization system focused on delivering superior business results and a positive change in the organizational culture at each stage of its implementation. In the first part of the implementation work, a diagnosis was made with the run to target methodology to see what the company's situation was. The problems found were the lack of objectives in each area of work, lack of a well-defined organizational culture, lack of a training plan based on a diagnosis of needs. Afterwards, an action plan was executed to change the organizational culture. With this plan it was possible to train leaders of operational processes s",
