    "resumen": "The present project was carried out in the Chuin Bajo site of the Vista Florida Agrarian Experimental Station -INIA- in the period from May to October 2018 in a net area of 8,127.00 m2 which had as objective to validate the treatments: T0 tillage Traditional, T1 Minimum tillage and T2 zero tillage, its incidence in the physical properties of the soil (porosity, apparent density, real density and humidity), as well as the productivity and profitability of the hard yellow corn crop INIA-619-MEGAHIBRIDO. For the implementation in the field, the statistical design Completely Randomized Blocks was used, in which the Blocks studied were: the three irrigations made for the sampling and the treatments were the types of tillage: T0 Traditional tillage (control), T1 minimum tillage, T2 zero tillage. For soil sampling, pits were made in each experimental unit making a total of 18 pits from which samples were taken for the analysis of apparent density, real density, porosity, moisture and soil texture. The experimental results of porosity, bulk density, real density and soil moisture were subjected to the t test at 5% error probability and the paired Student's T test to evaluate whether the ex",
