    "area": "Logística y Cadena de Suministro",
    "resumen": "Stuffing science began to flourish in the 1950s, with simple tests of sands and coal pumping in moderate concentrations. This science has gradually evolved to include pulp pumping in the food industry and process industries, coal and oil blends as new fuels and numerous mixtures of minerals with water. What is transported is a pulp that is a mixture of solids and liquids in different proportions whose physical characteristics depend on factors such as the type of ducts for transport, viscosity, pulp density among others. This work is carried out in the San Ignacio mine of Morococha, whose geology allows to exploit these mineralized bodies under the mechanized cutting and filling method and chambers and pillars, to achieve the established production objectives, using appropriate machinery for these purposes from dumpers and dumpers. and brought to surface with trolley line directly from the Ore pass, to guarantee this the service system must be optimal, one of them filling the exploded pits to be able to return the stability to the structures, to give floor for work for the machinery in conditions safe thus speeding the mining cycle. This is the origin of the main objective in this ",
