    "titulo": "Diseño e implementación de un modelo de gestión de compras e inventarios de los materiales de embalaje de espárrago fresco para reducir los costos logísticos de una empresa agroindustrial de La Libertad en el año 2018",
    "autor": "Sedano Rosas, Sheyla; Suarez Grados, Carlos",
