    "anio": 2019,
    "area": "Logística y Cadena de Suministro",
    "resumen": "This research is focused on the management of purchases and inventories of fresh asparagus packaging materials from an agroindustrial company in La Libertad. Its objective is to demonstrate that through the design and implementation of a purchasing and inventory management system it is possible to reduce the logistic costs incurred by the company, and on the occasion, to generate a competitive advantage. To achieve this, it was made a diagnosis of the situation that the company went through at the beginning of the study from a logistic perspective. We identified that the company used the MRP system, but due to the high variation of the sales projections, the company had stock breakdowns or generated over stock. Likewise, it was identified that the purchasing process was bureaucratic and that the company didn’t have established purchasing strategies. Then, materials were classified using the multicriteria ABC technique, and the most relevant materials were identified. For this materials, the replacement point, purchase lot size and safety stock were determined based on the continuous review system with replacement point. The purchasing procedure was modified to turn it into an agile",
