    "resumen": "ABSTRACT The objective of the research was to environmentally manage solid waste in the company Aquaculture and Fishing S.A.C., in Guaynuna Bay to prevent negative impacts. It was a descriptive and transversal investigation. The sample was non-probabilistic and formed by the company ACUAPESCA S.A.C. In the results it was found that the sources of non-hazardous solid waste generation were the administrative areas, production, quality control, storage, maintenance, changing rooms and hygienic services. Likewise, the areas that generated hazardous waste were the warehouse and production. According to the above, organic solid waste accounted for the largest amount (310.81 MT). With regard to the physical composition of solid waste, it was observed that organic waste was generated with the highest proportion (99.37%). In the assessment of environmental impact, it was identified that organic and inorganic solid waste (each with 24 points) generated in the production area, were those that generated the greatest environmental impact (not critical). It was concluded that the solid waste management carried out by the company ACUAPESCA S.A.C., was found in the provisions of the General Solid ",
