    "resumen": "The main objective of this research was to improve the level of customer satisfaction of the company Tambos Perú SAC, through the design of a quality management system based on ISO 9001: 2015, with strategies such as the SWOT matrix, mapping and interrelation of processes and scope definition. The methodology applied in the research is of a deductive nature, its design was preexperimental, with the population as a whole being the clients of the sales channels and as shown by the customers belonging to the modern channel, since they have relevance in the sales volumes. Where began with the diagnosis of the level of customer satisfaction, this was done through an internal audit applied to the company, which was formulated based on the guidelines of the client of the modern channel, the result of this audit was 53%. Then we proceeded to diagnose the quality management system through the checklist of compliance with the requirements of ISO 9001: 2015, reaching a 23% compliance, which is why it was necessary to design the documented information of each point of the quality management system, procedures were elaborated where it is indicated step by step how to assign resources, functions",
