    "titulo": "Implementación de un plan de mantenimiento preventivo para remolques y su impacto en la disponibilidad de unidades de la empresa Induamerica servicios logísticos s.a.c",
    "autor": "Esquives Sánchez, Jeancarlos Irvin; Mayta Salazar, Yurfa Aditha",
