    "area": "Logística y Cadena de Suministro",
    "resumen": "This paper describes the elaboration and implementation of the preventive maintenance program for trailers of the company INDUAMERICA LOGISTICAL SERVICES S.A.C. The implementation of the preventive maintenance program in INDUAMERICA LOGISTICAL SERVICES S.A.C. aims to guarantee the operational readiness of the company´s trailers, in an efficient and safe way, in order to contribute towards achieving the objectives established by the company. Firstly, was conducted the diagnostics of the maintenance function within INDUAMERICA LOGISTICAL SERVICES S.A.C; describing the strengths and weakness is in the connection. During the implementation was carried out the total inventory of trailers belonging to the company, then the criticality index was determined for each of them. The preventive maintenance program was designed in basis on critical points, which consists of tasks in specific functional systems within the trailers. Afterwards, formats were produced to support on maintenance management in the company, all these formats in concert with the computer program in Excel format that was developed, will enable the maintenance of an organized and controlled way. After six months from the m",
