    "resumen": "The present research work contains information on the technical economic study for the installation of a plant of three types of bricks in the Jequetepeque valley: Hueco 12, King Kong 18 and Tambourine 12. The study is based on the existence of a dissatisfied market since the wide variety and quality of bricks in the Jequetepeque Valley is not available. A survey was carried out based on the non-probabilistic sampling for convenience applied to two samples: Contractors and Companies Subcontractors of bricks. The methodology used was descriptive empirical since it seeks to specify the properties, characteristics and important features of the phenomenon that is being analyzed. The techniques of information collection were surveys, bibliographic review, statistics of the first indicators of the sector and direct observation. Likewise, the processing techniques were documentary and virtual review and review of previous results. To carry out the technical study, the following variables were used: commercial, technical, administrative and economic feasibility with their indicators: project demand, installed capacity, number of profiles required, VANE, TIRE, VANF, TIRF respectively. The s",
