    "anio": 2018,
    "area": "Producción y Operaciones",
    "resumen": "El objetivo del presente trabajo es dar a conocer la repercusión de los productos agroindustriales azucarados en el consumo de alimentos. En este estudio se investigó sobre los azucares y edulcorantes en general dando mayor énfasis a sus efectos sobre la salud humana. Asimismo, se investigó sobre la situación del consumo, regulaciones y recomendaciones sobre la ingesta de los azucares. Es importante remarcar las consecuencias que genera el consumo excesivo de alimentos con alto contenido de azucares sobre todo de sacarasa y azucares libres, responsables de una serie de enfermedades; por tanto, es necesario que los organismos regulen el contenido de azucares en alimentos a menos del 5% para disminuir sus efectos nocivos.",
