    "anio": 2018,
    "area": "Gestión de Proyectos",
    "resumen": "In order to achieve the objectives of the microenterprises, they develop their activities looking for their economic and financial growth, but often they can not alone, and therefore they go to third parties to obtain money and thus open more markets in other places, increase its commercialization, build or acquire new plants, or make another investment in which the company can benefit. As a problem, many microbusinesses in the Cajabamba district do not have a financial advisor to guide them and help them choose an investment or make an appropriate decision on which financing to choose, taking a bad decision and having as a consequence the high costs that You have to pay for the use of that required money, causing the economic slowdown, quantitative losses or even the closing of the business, being detrimental to the purpose for which this company was created. This could be avoided if the microentrepreneurs were financially advised and thus be able to finance themselves and invest appropriately and that, in this way, the microenterprise can have a financial potential that allows them to grow economically. The main objective of the present investigation is to demonstrate that the fi",
