    "area": "Gestión de Proyectos",
    "resumen": "El objetivo del artículo presentado es determinar cómo incide el comercio electrónico en el nivel de ventas, de las productoras de calzado pymes de la provincia de Trujillo. La presente investigación de la tesis doctoral, se ha desarrollado desde una perspectiva, descriptiva correlacional con un enfoque cuantitativo considerando dos variables. Se aplicó dicho modelo a fin de poder investigar la incidencia que existe del comercio electrónico en las Productoras Pymes del sector de la industria del calzado. Las pymes de este sector tienen diversos problemas económicos, como la baja producción de calzado, incremento de costos de la materia prima, los insumos, precios competitivos, etc., Se estimó un modelo de investigación causal para evaluar la incidencia de la presente investigación. El diseño de la presente investigación aplicado fue no experimental, descriptivo correlacional con un enfoque cuantitativo. Como técnica de investigación se empleó la encuesta a fin de determinar los objetivos planteados en la investigación. Las conclusiones a las que se llegó es que el sistema de ventas de las productoras de calzado Pymes de la provincia de Trujillo no es rentable y la herramienta del c",
