    "resumen": "Esta investigación tiene el objetivo de conocer los problemas conductuales y socioeconómicos presentes en la I.E Enrique Morales Pumarica, ubicado en la urbanización Los Álamos, relacionándolos con la arquitectura para plantear criterios que tengan impacto positivo frente a estos problemas. Es importante porque permitirá tener un proyecto para mejorar la infraestructura y calidad educativa, para un mejor desarrollo educativo, económico y social del estudiante. Se identificó los problemas conductuales, problemas de comportamiento y entorno social; y socioeconómicos, como característica económica y problemas sociales en los estudiantes; y fichas de observación para analizar las dimensiones y criterios arquitectónicos del colegio según la Norma técnica para el diseño de locales escolares y aspectos a criterio del autor para identificar a detalle los problemas que aqueja el colegio. Los resultados afirmaron que los estudiantes tienen problemas socioeconómicos y conductuales influenciados por su entorno social; en las fichas de observación se demuestran las deficiencias en su diseño, criterio arquitectónico, pedagógico y estructural. Según los resultados, se concluye y recomienda que lo",
