    "area": "Logística y Cadena de Suministro",
    "resumen": "Se determinó la entomofauna asociada al proceso de descomposición de restos cadavéricos de Sus scrofa L y su relación con la temperatura y humedad durante mayo a setiembre del 2017. Se utilizó dos especímenes el modelo animal Sus scrofa como biomodelo por poseer la misma distribución interna de los órganos del ser humano, cada espécimen fue colocado en campo abierto en diferentes periodos (julio y agosto) en jaulas adaptadas para la captura de los diferentes estadios evolutivos de la fauna cadavérica, registrándose la temperatura y humedad ambiental; las colectas se realizaron diariamente por un periodo de 20 segundos, los especímenes fueron identificados mediante el uso de claves taxonómicas. En el primer cerdo (julio) el género más abundante fue Chrysomya y el que se encontró en menor cantidad fue Muscidifurax raptor. Además, en este biomodelo se identificaron insectos en cuatro fases de descomposición, mientras que el en cerdo B solo se identificaron insectos en tres fases, pues en la primera fase no presentó especímenes. En el segundo cerdo, el género más abundante fue Cochliomyia y el de menor cantidad fue Muscidifurax raptor. Se determinó que la temperatura juega un rol muy i",
