    "anio": 2017,
    "area": "Gestión de la Calidad",
    "resumen": "RESUMENLa experiencia tuvo como objetivo determinar la calidad biológica del río Amojú, ubicado en Jaén, departamento de Cajamarca, en base a la caracterización de los parámetros biológicos presentes, empleando como medida la composición y abundancia de la fauna bentónica de macro invertebrados. Para lo cual se seleccionaron 6 estaciones de muestreo, desde los 549 a 1236 msnm, se analizaron parámetros biológicos a través de la identificación de los macroinvertebrados bentónicos in situ, asi como ex situ, identificándose 28 familias de macroinvertebrados. Además se estableció que la calidad de agua de la cuenca del río Amojú, basado en el Indice Biótico para los ríos del norte del norte del Perú nPeBMWP, era de calidad aceptable para las estaciones de muestreo E-1, E-2 y E-6, mala para las estaciones de muestreo E-4 y E-5, mientras que la estación E-6 fue de regular. Palabras claves: Indice biológico, macroinvertebrados, nPeBMWP, Jaén, río. ABSTRACT The experience was to determine the biological quality of Amojú river, Jaén Cajamarca, based on the characterization of biological parameters present, as measured by the composition and abundance of benthic macroinvertebrate fauna in an ",
