    "resumen": "RESUMEN Se investigó la reproducción y el aporte de crías de Carassius auratus “goldfish” con diferente alimento en sistema cerrado en Trujillo-Perú 2015. Se experimentaron con cinco reproductores maduros sexualmente, los cuales se acondicionaron en acuarios de 140 L con líneas de aire, luz y filtros mecánico y biológicos para conseguir el número de puestas, frecuencia, fecundidad, tiempo de eclosión de huevos, número de crías y supervivencia. Se les alimentó con 70 % de alimento vivo y 30 % de Nutrafin Max alimento tipo escamas a una tasa de alimentación del 2%. La reproducción de los goldfish machos Yamagata 1, Yamagata 2 y Oranda con la Redcap hembra se obtuvo desde agosto a octubre con una proporción sexual de 3:1. La puesta promedio fue de 5000 huevos y 3750 crías con 85% de supervivencia alimentadas con nauplios de Artemia franciscana y Tubifex tubifex. Palabras clave: Reproducción, crías, Carassius auratus, goldfish, alimento, sistema cerrado. ABSTRACT The reproduction and breeding of Carassius auratus \"goldfish\" fry with different food in closed system in Trujillo- Peru 2015 was investigated. It was experimented with five brood stock of sexual maturity, which were condition",
