    "id": "unt-paper-agroindscience-1274-1213",
    "titulo": "Certificar con Buenas Prácticas Ganaderas hace más eficiente los recursos de una explotación pecuaria",
    "autor": "López, Jean; Cordero, Aída",
    "asesor": "Castillo Chung, Aldo Roger",
    "anio": 2017,
    "area": "Gestión de Proyectos",
    "resumen": "Con el objetivo de hacer más eficiente los recursos de la explotación pecuaria, se certifica el centro de engorde, denominado Fundo Buenavista, en Buenas Prácticas Ganaderas (BPG), basado en la normativa GLOBALGAP. En el presente artículo se presenta el grado de cumplimiento de la normativa GLOBALGAP de las dos auditorías realizadas antes de obtener la certificación y de las auditorias de certificación del año 2012 al 2016, además de exponer la viabilidad y restricciones que se presentaron en el proceso de certificación en BPG. En la primera auditoria el porcentaje de cumplimiento de la normativa GLOBALGAP fue de 44,3% de las obligaciones mayores (OMa), 21,6% de las obligaciones menores (OMe) y 31,8% en las recomendaciones(R); mientras que en la segunda auditoria, el porcentaje de cumplimiento fue de 79% de las OMa, 85% de las OMe y 100% de las R. Finalmente la empresa ganadera logra certificar sus operaciones, al año siguiente, año 2012, al cumplir el 100% de las OMa, 95% de las OMe y el 100% de las R, manteniéndose desde aquel año certificada. Permitiendo al productor ser más competitivo y disminuir sus costos de producción mediante el uso más eficiente de los recursos de la expl",
