    "anio": 2017,
    "area": "Producción y Operaciones",
    "resumen": "El objetivo del presente trabajo fue evaluar la influencia de la adición de dos fuentes de calcio sobre los parámetros productivos de pollos de carne de la línea Cobb 500. Se utilizó un Diseño Completamente al Azar y la prueba Tukey al 5%, se evaluaron 80 pollos, con dos tratamientos y cuatro repeticiones, los tratamientos fueron: tratamiento uno (T1) agregado calcáreo, fuente inorgánica y el tratamiento 2 (T2) conchuela, fuente orgánica, ambas con un tamaño de partícula de 180 μ (micras). Los resultados de la evaluación a los 21 días, fueron 820,38 y 843,5 g (gramos) para el Peso y 796,00 y 798,3 g para la ganancia de peso. El contenido de ceniza en la tibia de los pollos fue de 57,63 y 58,74 % y, 42,24 y 40,31 % para el contenido de calcio. En las variables indicadas, no se encontraron diferencias estadísticas significativas entre tratamientos (P < 0,05). Pero en el consumo y conversión alimenticia se hallaron diferencias estadísticas significativas (P < 0,05), obteniendo 1113,10 y 11081,90 g para el consumo de alimento y, 1,40 y 1,36 para la conversión alimenticia. En conclusión, ambas fuentes de calcio pueden ser utilizadas en la alimentación de pollos de carne, sin embargo, se",
