    "resumen": "La presente investigación tuvo como finalidad medir el impacto de un Programa Ergonómico en la Productividad de una Empresa de Fabricación de Envases de Hojalata; para ello se empleó una metodología descriptiva y de carácter no experimental; donde la población estuvo conformada por los trabajadores del área de producción de la empresa de manufactura de envases el cual asciende a 30 trabajadores. En el presente estudio se analizaron a todos los trabajadores, por lo que no se aplicó un muestreo, sino que se realizó un censo. Los datos fueron recogidos a través de un instrumento basado en la metodología REBA la cual permitiría evaluar las posturas de los trabajadores mientras realizaban sus tareas diarias; así mismo se midió la productividad de las horas hombre con respecto a los niveles de producción en cada una de las líneas analizadas. Así mismo los resultados demostraron que los procesos seleccionados obtuvieron puntuaciones iniciales que oscilaban entre 11 y 12 según la escala determinada por el Método REBA. De la misma manera se demostró que la productividad de la mano de obra ascendía a un promedio de 339,7 láminas por hora hombre. Finalmente, también se pudo identificar que la",
