    "resumen": "Se investigó la relación entre la crocancia sensorial y el valor de los picos sonoros de galletas dulces de avena y granola marca Quaker en envases de laminado de aluminio con polietileno de baja densidad, empleando pruebas aceleradas a temperaturas de 30, 40 y 50°C en un ambiente con 100% de humedad relativa producido por baño María a presión atmosférica. Se evaluó la crocancia a las 0, 7, 24, 41 y 48 horas a través de picos sonoros (dB), obtenidos en una cámara acústica con ayuda de un sonómetro y pruebas paralelas de análisis sensorial de su crocancia mediante pruebas hedónicas, utilizando 14 panelistas entrenados; estableciéndose una relación entre ambas a través de la determinación del punto de corte y vida útil en condiciones de alta humedad relativa. Se observó en el tiempo una disminución del valor de los picos sonoros (dB) en las galletas durante las pruebas aceleradas a temperaturas de 30, 40 y 50 °C, las que mostraron una cinética de orden cero y elevados coeficientes de determinación R2 (0,96 a 0,99). Igualmente una disminución de la crocancia sensorial al aumentar la temperatura. Se determinó un elevado coeficiente de determinación de 0,93 entre los picos sonoros y la ",
