    "area": "Gestión de la Calidad",
    "resumen": "La presente investigación, se llevó a cabo en la planta de hielo “PRC. S.A.C.”, cuya actividad es la producción y comercialización de hielo principalmente utilizados en la industria pesquera; tiene por objeto de estudio el sistema actual de refrigeración por compresión de vapor con interfriador. Luego, se analizará el sistema de refrigeración por compresión de vapor con sistema de escala de compresores. Estas evaluaciones tienen la finalidad de determinar la eficiencia exergética a través de las irreversibilidades, de tal manera que nos permita comparar y tener una mejora en el coeficiente de performance. Posteriormente, y finalmente, se realizará una evaluación termoeconómica de dichos sistemas que permita analizar a la empresa la conveniencia en estudio, mediante la reducción de sus costos de producción usando de forma eficiente sus procesos productivos, brindando productos de calidad, y siendo competitiva en el mercado. Se evidencia que al realizar una evaluación termoexergética al sistema de refrigeración por compresión de vapor con sistema de escala de compresores, se logrará incrementar la eficiencia exergética, reducir las irreversibilidades y la exergía destruida; sobre tod",
