    "anio": 2017,
    "area": "Producción y Operaciones",
    "resumen": "En el presente estudio se hace uso del software Flow simulation para analizar un inyector tipo Y con el método computational fluid dynamics (CFD). Este tipo de investigación ayuda a comprender el comportamiento de las dos variables principales en la atomización de fluidos, el campo de presión y velocidad. Por la naturaleza milimétrica de las dimensiones del accesorio, hace prácticamente imposible realizar un seguimiento de las variables a escala real. Se hicieron uso de dos fluidos, actuando como combustible atomizado el etanol y como gas de atomización el aire. Primero se realizó el mayado del sólido para poder analizar la influencia de la presión en el flujo másico del etanol, y aparte la influencia de la presión sobre el flujo de aire, de donde se obtuvieron, después de muchas iteraciones, dos gráficas de comportamiento cuasi parabólico. Uniendo finalmente los dos fluidos, se aplicaron líneas de trayectoria a lo largo de la longitud del inyector para poder observar el comportamiento de las variables en todo el eje Z.",
