    "resumen": "This research has the main objective to determine the influence that proper relocation of Maestranza-turbines workstations has on productivity of the factory of Agroindustrias San Jacinto S.A.A. The methodology used in the research was descriptive, so the research focused on the collection and analysis of information in this way, propose a solution to the problem encountered in the factory. The sample for the study was the selected process productivity maintenance performed during the study period. The investigation began with a diagnosis of the current situation in the factory, highlighting the deficiencies observed. Looking up the SAP system, the list of products manufactured by the factory in the study period was obtained. Then it was identified production lines, linking products with equipment used. Since not all lines have the same production capacity, it was selected the most important by a Pareto chart, determining that only 7 are those representing approximately 80% of the work area. In addition, the list of productive resources of factory was described. With this information, the redistribution under the guidelines of Systematic Layout Planning was designed. Thus, using th",
