    "asesor": "Caballero Alayo, Carlos",
    "anio": 2016,
    "area": "Gestión de Proyectos",
    "resumen": "Las nuevas Tecnologías de la Información y Comunicación generan en la sociedad un nuevo contexto provocando cambios en los procesos de socialización, cognitivos y conductuales. Estas herramientas están modificando el modo de comunicar, consumir, pensar, trabajar y de acceder a la información. En este contexto, una de las herramientas que aparece en el entorno del adolescente, el WhatsApp se consolida como una de las primeras formas de comunicación ya que, con su uso, los adolescentes complementan su comunicación interpersonal favoreciendo en ellos aspectos tales como la sociabilidad respecto a la búsqueda de un socio o compañero y la pertenencia a un grupo, tan importante en estas edades. Esta aplicación es un sistema fácil, gratuito, íntimo, inmediato, personalizable, con un número variable de usuarios, con un lenguaje propio y con la posibilidad de ser controlada, circunstancia esta que hace incrementar lo íntimo. En el presente trabajo se pretende analizar, el uso masivo de la aplicación del WhatsApp, y su grado de influencia que ejerce sobre el nivel ortográfico de los estudiantes de la escuela profesional de Lengua y Literatura y por otro lado su repercusión en la enseñanza co",
