    "resumen": "El presente informe de prácticas Pre-Profesionales tiene por objetivo conocer las actividades que se realiza en el área de Control de Calidad como analista auxiliar de Materia Prima en el laboratorio VITALINE S.A.C. Esta empresa tiene como principal actividad la fabricación de productos oftalmológicos y a su vez ofrece servicios de maquila para otras empresas del rubro. En este informe se hace un enfoque de las actividades que se ejecutan en la sub-área de Materia Prima, como: muestreo, análisis, elaboración de reportes y protocolos de materia prima, revisión, actualización y modificación de las especificaciones técnicas y técnicas analíticas, así como todo lo que implica la generación de estándares secundarios, y el análisis de material de envase; actividades que contribuyen a la formación del profesional Químico Farmacéutico. Todo esto permitió adquirir conocimientos, destrezas y habilidades en cada una de las actividades que ejecutó durante el desarrollo de las prácticas pre-profesionales",
