    "area": "Gestión de Proyectos",
    "resumen": "This paper addresses the economic valuation of the electric furnace slag generated by Empresa Siderúrgica del Peru SAA - SIDERPERU located in the district of Chimbote, Santa, Ancash, for use as aggregate in the manufacture of concrete. To establish the technical feasibility of electric furnace slag as aggregate for concrete, physical and chemical properties provided by SIDERPERU were collected, and the results obtained by a local company concretera concrete compressive strength tests made with electric furnace slag SIDERPERU. After determining the technical feasibility commercial analysis was performed to establish the conditions for marketing within the province of Santa, identifying potential customers, competition, sales price and distribution channels, finding that this practice of environmental assessment is feasible, which would generate an income to company to S/. 402 000 per year and intangible benefits by projecting an environmentally responsible image and adopting an alternative to curb the environmental impact of the deterioration of the quarries in exploitation of building materials.",
