    "id": "unt-alicia-handle-net-20-500-14414-1117",
    "titulo": "mejoramiento de la performace del sistema de control de un inyector de flujo laminar de agua para fines de ornamentacion",
    "autor": "Altamirano Ruiz, Suiler Samir",
    "asesor": "Docente Asesor — Escuela de Ing. Industrial UNT",
    "anio": 2016,
    "area": "Gestión de Proyectos",
    "resumen": "El no existir empresa nacional que fabrique inyectores de flujo laminar de agua obliga a empresarios a adquirir los productos desde el extranjero a precios altos, y/o comprar accesorios nacionales para tratar de igualarlos, pero que no cuentan con las expectativas deseadas ni con el mantenimiento adecuado, utilizando solo boquillas que son caras e ineficientes; ocasionando desperdicio de agua y pisos resbaladizos por ser la salida un flujo demasiado turbulento. De acuerdo a la Realidad Trujillana, el número de fuentes ornamentales se ha incrementado bastante, pero debido al empirismo existente en ésta área, estas obras no cuentan con ningún criterio ingenieril, existiendo incoherencia entre el diseño y la implementación. Por tal motivo se desarrolla en esta tesis la ingeniería necesaria para la mejora de la performance de un inyector de flujo laminar, realizando un estudio y diseño del sistema, e implementando un control proporcional a lazo abierto utilizando un PLC, un SCADA y un Variador de Velocidad, para la realización de ensayos en laboratorio con diversos inyectores, modificando sus parámetros adimensionales y de operación, hasta la obtención del objetivo propuesto. Concluyen",
