    "resumen": "El presente trabajo tiene como propósito, el estudio, formulación e implementación de células de producción en el área de armado de la empresa Negocios e Inversiones HGS E.I.R.L de calzado para dama para aumentar su productividad.Para lograr este estado, se realizó reuniones con el gerente para señalar las expectativas, además se identificó el producto representativo, el cual resulto de la evaluación de la demanda de los productos a producir para el mes de Mayo a Junio del 2015. Primero se identificó la problemática dentro de la empresa, permitiendo conocer los principales problemas que existen; para el desarrollo del proyecto se analizó el estado inicial del área de armado – ensuelado, se tomaron los tiempos reales para cada una de las actividades del proceso de armado – ensuelado, posteriormente se realizó el estudio de tiempo y de esta manera se halló los tiempos estándares. En coordinación con el gerente se eligió implementar 5’sy las células de manufactura. El primero consistió en cinco pasos, selección, orden, limpieza, estandarización y disciplina. Por otro lado para el diseño e implementación de las células, se determinó el tiempo Takt-Timeel cual resultó ser 2 horas con 29",
