    "area": "Producción y Operaciones",
    "resumen": "Se evaluó el efecto ecotoxicológico de la benzodiacepina y para-aminofenol sobre larvas de Aedes aegypti en condiciones de laboratorio; para lo cual, se siguió la metodología de observación directa en un diseño en bloques con estímulo creciente en base a tres repeticiones, cuyas concentraciones fueron determinadas mediante el método logarítmico y la técnica de Reish y Oshida, en un tiempo de exposición al fármaco de 24 y 48 horas, teniendo como resultados que ambos fármacos presentan efecto letal sobre las larvas de A. aegypti, con la diferencia de que a las 48 horas, el efecto letal de la benzodiacepina supera al causado por el para-aminofenol y según los análisis de varianza, existe diferencia significativa entre los tratamientos y tiempos de exposición, comprobado mediante la comparación de promedios de la prueba de la Mínima Diferencia Significativa Honesta, que demuestra que cada concentración tiene un efecto letal, lo que permite concluir que los fármacos tienen efecto letal sobre las larvas de A. aegypti.Palabras clave: Ecotoxicología, Aedes aegypti, benzodiacepina, para-aminofenolABSTRACTEcotoxicological effect of benzodiazepine and para-aminophenol was evaluated on Aedes a",
