    "id": "unt-paper-sciendo-1055-983",
    "titulo": "GESTIÓN INTEGRADA DE RECURSOS HÍDRICOS DE LA CUENCA DEL RÍO JEQUETEPEQUE, PERÚ",
    "autor": "Guerrero Padilla, Ana Marlene",
    "asesor": "Castillo Chung, Aldo Roger",
    "anio": 2016,
    "area": "Gestión de la Calidad",
    "resumen": "El presente ensayo tiene como objetivo examinar la situación de la actual gestión de los recursos hídricos en la cuenca del río Jequetepeque, Perú, desde una perspectiva nacional y regional de gestión integrada de recursos hídricos (GIRH). La problemática de la cuenca del río Jequetepeque se enmarca dentro del existente pluralismo normativo y de la valoración multidimensional del agua. La actividad minera en la cuenca ocasiona el mayor impacto en el manejo del recurso hídrico y compite por el uso del agua con otras actividades como las agrícolas, ganaderas y de consumo humano. Hay que prestarle especial atención a las escalas espaciales en términos de la variación geográfica y las posibles interacciones aguas arriba-aguas abajo, así como a la variación de la disponibilidad de agua, estacional, anual o de largo plazo. La cuenca del río Jequetepeque carece de GIRH. Para implementar una GIRH se requiere un marco legal, institucional y financiero que reconozca sus cuatro dimensiones: recurso (calidad y cantidad), usuarios, escalas espaciales y temporales. Existe una capacidad incipiente y débil para la concertación entre los actores en relación a la solución del problema de la contamin",
