    "area": "Gestión de Proyectos",
    "resumen": "El objetivo del presente trabajo fue diseñar e instalar un pasteurizador solar en una zona rural de la provincia de Chao de la Región La Libertad-Perú, en el establo de la familia Vilcachahua (latitud 08°30´37´´, longitud 78°39´04´´), en el cual se procesó leche de cabra (LC) inmediatamente después de su ordeño. Se evaluó el efecto tiempo-temperatura en la pasteurización de leche y se realizó una comparación económica frente al uso alternativo de gas propano y energía eléctrica como fuente de calor. El pasteurizador contó con colector solar (CS) de 2 m2 con inclinación N-S de 13,89°, un tanque acumulador-intercambiador de calor (TAIC) provisto de serpentín de acero inoxidable (SAI) de 9,71 m, por donde circularon 3 batch de 10 L de leche a 2,15 L/s. El control de temperatura se realizó con tres sensores LM35 acoplados a una tarjeta Arduino Uno y a un ordenador en la cual se instalaron drivers de la tarjeta, el software LaVIEW y una interfaz de LabVIEW para Arduino, en donde se realizó la programación gráfica. El pasteurizador solar funcionó 6 horas y debido a las condiciones climáticas (04.03.2015) se utilizó un sistema auxiliar de gas propano por 20 minutos, cumpliéndose el tratam",
