    "id": "unt-paper-agroindscience-1060-988",
    "titulo": "Aprovechamiento de los residuos del membrillo (Cydonia oblonga L.) como fuente de compuestos bioactivos",
    "autor": "Espinoza, Mario; Gómez, Elvia",
    "asesor": "Arango Retamozo, Solio Marino",
    "anio": 2016,
    "area": "Gestión de Proyectos",
    "resumen": "Nuestras ciudades generan cada vez más cantidad de residuos cuya disposición final se realiza en botaderos a cielo abierto constituyendo un problema para la salud pública, además los elevados volúmenes suponen importantes costos de recolección. Pese a esto, los residuos orgánicos también son una fuente importante de compuestos bioactivos que pueden ser reutilizados debido a sus propiedades favorables, pudiendo tener un efecto benéfico para la salud humana. El presente estudio tuvo como objetivo evaluar la técnica del secado por aire convectivo (AC) combinado con variables de temperatura y tiempo sobre el contenido de fenoles y flavonoides totales para el aprovechamiento de los residuos agroindustriales del membrillo (Cydonia oblonga L. variedad “Serrano”). Fue utilizado un Diseño Compuesto Central Rotable (DCCR) con temperatura entre 50 y 70 °C y tiempo entre 150 y 240 minutos. Se utilizó Cromatografía Líquida de Alta Resolución (HPLC) para determinar el contenido de flavonoides totales en los ensayos. Se determinó que el secado por AC produjo una reducción del 35% aproximadamente en contenido de fenoles totales cuando se trabaja con temperaturas de 48 a 58 °C y tiempo de 140 a 220",
