    "titulo": "Influencia de la incorporación de aloe vera en yacón (Smallanthus sonchifolius Poepp. & Endl) mediante impregnación a vacío en la aceptación sensorial del producto",
    "autor": "Rojas, Erika; Oblitas, Jimy",
