    "area": "Gestión de Proyectos",
    "resumen": "La aceptabilidad por el consumidor y la determinación de diferencias entre productos se realiza a través del análisis sensorial, una disciplina científica a través de la cual el evaluador sensorial evoca, analiza, mide e interpreta respuestas humanas a estímulos percibidos a través de los sentidos. Es por ello que se hace necesario realizar este tipo de estudios para lanzar al mercado productos nuevos, como el yacón impregnado con aloe vera. El objetivo de la presente investigación fue determinar la influencia de la incorporación de aloe vera en yacón (Smallanthus sonchifolius poepp. &amp; endl) mediante impregnación a vacío en la aceptación sensorial del producto. Se utilizó la metodología de análisis descriptivo para categorización cuantitativa relativa con la utilización de una escala no estructurada o adimensionada de 12 cm con panelistas semientrenados. Para el análisis de datos se hizo uso del software de análisis estadístico XLSTAT. La evaluación sensorial mostró que el p-value para el color fue 0,101 y para el sabor fue 0,045, lo cual muestra que no encuentran diferencia significativa para el color (p > 0,05); siendo el sabor significativo para este análisis (p < 0,05). El ",
