    "titulo": "Influencia de la temperatura y concentración sobre el comportamiento reológico de la pulpa concentrada de aguaymanto (Physalis peruviana L.)",
    "autor": "Bustamante, Roxana; Oblitas, Jimy",
    "asesor": "Reyes Cruzado, Jorge Luis",
    "anio": 2016,
    "area": "Logística y Cadena de Suministro",
    "resumen": "El comportamiento reológico es un factor importante en el control de calidad en determinadas fases de elaboración, empaque y almacenamiento de los productos, así como para proporcionar parámetros fundamentales en el diseño de máquinas para su procesamiento y diseño de empaque, en los cálculos de ingeniería, en el diseño del proceso. El objetivo de la presente investigación fue determinar la influencia de la temperatura y concentración sobre el comportamiento reológico de la pulpa de aguaymanto. Las medidas reológicas fueron realizadas mediante un viscosímetro Brookfield DV- E. Así mismo se determinó el tipo de fluido y el modelo matemático que más se ajusta. La pulpa de aguaymanto estudiada en sus diferentes concentraciones y temperaturas obedece a la ley de potencia con valores de n entre 0 y 1, y no presenta umbral de fluencia; son, por lo tanto, fluidos pseudoplásticos. En la determinación de las constantes reológicas fundamentales del producto se debe controlar, principalmente, la concentración de medición, dado que estos parámetros han demostrado ejercer un efecto significativo sobre k y n. Las constantes reológicas k y n, calculadas utilizando el método MITSCHKA, pueden servi",
