    "id": "unt-paper-agroindscience-1128-1214",
    "titulo": "El pH de los suelos de la Sierra Central del Perú en la calidad industrial de hojuelas de Solanum tuberosum L. var. Capiro",
    "autor": "Aliaga, Isaac; Velásquez-Barreto, Frank",
    "asesor": "Calderón Cruz, Ana María",
    "anio": 2016,
    "area": "Gestión de la Calidad",
    "resumen": "Este trabajo se realizó en el distrito de Paca, en el anexo de Chuclu y laguna (Jauja), en el distrito de Zapallanga (Huancayo) y en el distrito de Mito (Concepción) durante la campaña agrícola 2013 - 2014 en suelos con diferentes pH y altitudes, con el objetivo de determinar si el pH del suelo influye en el contenido de azúcares reductores, sólidos totales y calidad en la fritura de los tubérculos de papa variedad Capiro (color, sabor y crujencia). Para la calidad de fritura se utilizaron tubérculos de papa Capiro con un peso 50 ± 10 g de cada tubérculo y una longitud de 15 ± 1 cm y grosor de 6,0 ± 0,5 cm de diámetro, la determinación de azucares reductores se realizó por el método DNS (3,5 ácido dinitrosalicílico) y para la determinación de la calidad de fritura de las hojuelas de papa se utilizó un panel de jueces semientrenados y para la evaluación sensorial una prueba de aceptación con escala hedónica de 4 puntos. El análisis de suelos para las localidades dio un rango de pH de 4,89 a 7,79; materia orgánica de 3,5 a 5,3%; contenido de nitrógeno de 14,4 a 17,0%; contenido en fósforo de 12,8 a 14,6 ppm y la concentración de potasio de 160,4 a 175,1 ppm. El porcentaje de azúcares",
