    "anio": 2016,
    "area": "Gestión de Proyectos",
    "resumen": "Se determinó serológicamente la competitividad simbiótica, de una cepa nativa de Bradyrhizobium sp. RC 458-01 eficientemente simbiótica, comparándola con una cepa patrón Bradyrhizobium sp. CIAT 71. La competitividad se evaluó mediante el porcentaje promedio de ocupancia de nódulos en Vigna unguiculata “Caupí”. Se prepararon jarras de Leonard modificadas, se agregó a cada jarra arena estéril y 3semillas de Caupí germinadas; las semillas fueron inoculadas con cultivos de Bradyrhizobium sp., CIAT 71 y RC 458-01, a una concentración de 1,2 x 10 9 bact./mL, formándose un inoculo mixto. Las jarras se colocaron durante 40 días a temperatura de 15° a 35°C y 40 a 80 % de humedad. Para la evaluación serológica se realizó la producción de anticuerpos de las dos cepas de Bradyrhizobium sp., para lo cual se procedió a inmunizar en Oryctulagus cunniculus “conejo”, vía intramuscular 1 mL de antígeno de rizobios más 1 mL de adyuvante completo de Freund; a los 14 y 21 días se inoculó con 1 mL de antígeno de rizobios más 1 mL de adyuvante incompleto de Freund, posteriormente se tomaron muestras de sangre para la obtención del suero inmune. El porcentaje promedio de ocupancia de nódulos se determinó ",
