    "area": "Gestión de Proyectos",
    "resumen": "Se realizó un trabajo de investigación con el propósito de mejorar la condición de vida de las madres de familia a través de su participación en la elaboración de mermeladas para la venta directa en el Sector VII del Milagro, Trujillo – Perú, con el supuesto que dicha actividad crece junto a una adecuada gestión de responsabilidad social. El estudio tuvo carácter proyectivo y aplicado, donde se dio solución a una necesidad de tipo práctica a las madres de familia, para ello como metodología se dispuso del diagnóstico, diseño y ejecución del plan de acciones para la elaboración de mermelada, utilizándose herramientas como encuestas, registro y/o base de datos, entrevistas y observación. Se identificó las mayores necesidades en base al Censo Poblacional UPN realizado el presente año. Se priorizó y determinó el problema socio-ambiental a resolver en la comunidad. Se analizó el problema por medio de la matriz de interrelación FDOR, y a partir de éste se formuló los objetivos del proyecto. Posteriormente, se elaboró y ejecutó el plan de acciones en base a la programación de actividades y sus respectivos indicadores. Se determinó que con la ejecución del plan de acciones para la elaborac",
