    "area": "Gestión de la Calidad",
    "resumen": "El objetivo del presente trabajo fue evaluar los impactos ambientales significativos generados por la actividad de la empresa Alpes Chiclayo S.A.C. en la producción de conserva de frijol de palo, midiendo las variables ambientales: la calidad del aire para medir NO2, O3, SO2 y H2S de acuerdo a lo contemplado en el D.S. 074-PCM, niveles de ruido en los diferentes puntos de la planta, material particulado midiendo los parámetros MP10 y MP2.5 y la calidad de agua fue determinada por el método de Plasma Inducido Acoplado (ICP). Para evaluar los impactos ambientales se utilizó el método de matrices bidimensionales que plotea acciones versus factores ambientales y utilizando el método de Fisher Davies se calificaron los impactos ambientales negativos en una escala de poco significativo, significativo y muy significativo, severo y critico anteponiendo el signo (-). Para los impactos positivos se antepuso el signo (+). Los resultados del monitoreo realizado utilizando el método de matriz bidimensional determinó que los impactos ambientales generados durante el proceso productivo fueron calificados como poco significativos; los impactos positivos fueron sobre la población, agua, suelo y pai",
