    "area": "Gestión de la Calidad",
    "resumen": "El objetivo del presente trabajo fue evaluar el efecto del estrés hídrico en los componentes del rendimiento y calidad del mosto de vid cv. Moscatel en el valle de Caravelí, Arequipa durante el ciclo productivo 2011 - 2012. Los tratamientos (T0 = 25, T1 = 20, T2 = 15, T3 = 30, T2 - T3 = (15-30) L/ planta.) no produjeron diferencias estadísticas en las características de área foliar, número de racimos y número de bayas. Contrariamente, hubo diferencias estadísticas significativas en el diámetro ecuatorial de las bayas (B1, B2 y B3), peso promedio de racimos (T0 = 11,50; T2 = 9,50 kg/cepa), así como en la calidad del mosto expresado en la densidad (T3 = 1,111; T2 - T3 = 1,106 mg/cm3), pH (T3 = 4,05; T1 = 3,90), grados Brix (T0 = 24,72º; T2 = 24,37º, a la quinta evaluación) y fenol como ácido gálico (T2 = 1,67; T0 = 1,53 mg/L). En conclusión, los tratamientos T2 y T3 produjeron las diferencias extremas comparados con el tratamiento testigo (T0).",
