    "anio": 2015,
    "area": "Gestión de la Calidad",
    "resumen": "La presente investigación se llevó a cabo para desarrollar una propuesta de un Plan de Manejo de Residuos Sólidos Urbanos en el distrito de Contumazá, provincia de Contumazá, región Cajamarca; como un instrumento de gestión para la Municipalidad Provincial de Contumazá, que le permita una metamorfosis de una gestión tradicional e ineficiente a una de tipo integral. Ya que la disposición final lo hace en un botadero a cielo abierto, no hay una recuperación de materiales aprovechables, la cobertura del servicio de limpieza pública es ineficiente, existen una serie de puntos críticos de acumulación de residuos y la tecnología empleada es obsoleta, por lo que sirve de punto de partida para la planificación de la gestión integral de los residuos sólidos urbanos en este lugar. Considerando lo antes mencionado, y en base a la evaluación de la situación actual de la Gestión de Residuos Sólidos; se elaboró una propuesta de un Plan de Manejo de Residuos Sólidos para el distrito de Contumazá; conteniendo las políticas, objetivos, metas, líneas de acción, plan de acción y monitoreo del mismo; con propuestas enfocadas en aspectos administrativos, de educación, tecnológicos y técnicos en la gest",
