    "resumen": "En este estudio se determinó el efecto de las suspensiones acuosas al 2, 3 y 4% del pericarpio de Sapindus saponaria sobre la población de Meloidogyne incognita en plantas de Asparagus officinalis cv. UC-157 F1 cultivadas en invernadero. Para ello, se utilizaron cuatro grupos de estudio de cinco macetas cada uno; constituidos por tres grupos experimentales tratados con las suspensiones acuosas mencionadas y un grupo testigo. En cada maceta se trasplantó una plántula de A. officinalis del cultivar mencionado y a los 30 días fueron inoculados 4000 huevos de M. incognita, luego en los grupos experimentales fue aplicada la primera dosis de S. saponaria y tres días después se añadió la segunda dosis. A los 90 días fueron evaluadas la tasa de multiplicación del nematodo (TMN), el índice de nodulación radicular (INR), la altura de las plantas, el peso seco de la parte aérea, de las raíces y el pH final del suelo. La TMN y el INR en los grupos experimentales fue menor con diferencia estadística altamente significativa (p<0.0001) comparado con el grupo testigo, sin embargo no hubo diferencia estadística entre los grupos experimentales (p>0.05), según la prueba de Tukey. Se concluye que las ",
