    "anio": 2015,
    "area": "Producción y Operaciones",
    "resumen": "Las riñas de gallos, en Paiján, son importantes espacios de socialización en los que se ponen en juego elementos como el honor, el prestigio y el estatus de los asistentes, esto conlleva la trasmisión generacional de esta práctica a través de la enseñanza de técnicas y conocimientos entre las familias, amigos y a la cohesión de una comunidad bien delimitada como son los galleros En la gallera se escenifican diferentes elementos de la cultura popular y festiva No son dos gallos peleando, es la vida de quienes ahí se juegan el destino, su suerte; vida que florece y fenece entre cuchilladas y sangre. Este conjunto de imágenes son la impronta de una tradición que vive al hacerse más cercana a la muerte.",
