    "titulo": "Diseño de una planta para la producción de tableros aglomerados a partir de residuos de envases de tetra pak en la provincia de trujillo",
    "autor": "Espinoza Cerrepe, Cristóbal Gonzaga; Chávez Peláez, Robert Estewar",
