    "titulo": "Influencia de la formalización de las mypes en la determinación de los costos de producción en las empresas del sector calzado del distrito el porvenir, provincia de Trujillo, departamento de la libertad, 2014",
    "autor": "Ugaz Barrantes, Clara Elizabeth",
