    "anio": 2015,
    "area": "Gestión de Proyectos",
    "resumen": "After many years of considering to micro and small enterprises (Mypes) as something marginal, obsolete, or illegal, both globally and in the Peru, is beginning to recognize the real importance of the sector and its vital role in the economic and social development. From politicians to homemakers, passing through all sectors of society as well as institutions representative, accepted today than the fate of the country and the well-being of millions of people require a sector micro and small business healthy and dynamic. There are many reasons that explain this change of opinion and perspective. The present study was conducted in the district El Porvenir, province of Trujillo, Department of La Libertad, with the participation of micro and small entrepreneurs working in formal and informal way and engaged in the manufacture of footwear. The overall objective of the research is to determine the influence of the formalization of the micro and small enterprises in the determination of the production costs. In this type of companies abounds informality due to lack of information, excessive bureaucracy, fear of losing the money managed, cultural aspects, mainly. These causes to encourage, ",
