    "resumen": "insectos encontrados en cadáveres de una escena criminal pueden ser usados como herramientas para una investigación forense, debido a que permiten estimar el intervalo postmortem y conocer el sitio donde ocurrió la muerte o si un cuerpo fue trasladado de un lugar a otro y el estado de descomposición o sucesión de microorganismos; por lo que nuestra investigación tuvo como objetivo determinar la sucesión entomológica que aparece en cadáveres de Oryctolagus cuniculus “conejo” expuestos al medio ambiente, para poder posibilitar la mejor compresión de la entomofauna y sus aspectos ecológicos en el proceso de descomposición cadavérica en condiciones de campo, teniendo en cuenta la temperatura y humedad relativa que por información bibliográfica actúan como factores de alteración en el proceso de descomposición, con lo que se encontró tres categorías ecológicas: necrófagas, predadoras y omnívoras, compuesta por especies del orden Díptera, Coleóptera, Himenóptera, Aránea y Escorpiones; siendo Díptera el orden con mayor incidencia en todas las fases de descomposición seguido por Coleóptera representado por la familia Dermestidae, lo que nos permite concluir que dicha familia puede ser cons",
