    "titulo": "Evaluación de harina de soya como fuente primaria en la producción de biomasa de Saccharomyces cerevisiae",
    "autor": "Gómez, Elvia; Estrada, Ademar",
    "asesor": "Romero Shollande, Carlos Aurelio",
    "anio": 2015,
    "area": "Gestión de Proyectos",
    "resumen": "Se formuló un medio de cultivo para crecimiento de Saccharomyces cerevisiae a partir de Harina de Soja como fuente principal en dos concentraciones (35 y 47.97 % de proteína bruta) y se reforzó los medios con sacarosa (C6H12O6), fosfato dibásico de Amonio (NH4)2HPO4, ácido fosfórico (H3PO4), Tiosulfato deSodio (Na2S2O3), agua (H2O) y ácido cítrico (C6H8O7) utilizado como buffer en diferentes concentraciones según fueron los requerimientos, bajo flujos de aireación constantes de 0.51 VVM. La evaluación de la producción de biomasa se realizó mediante la cinética de crecimiento con el modelo de Gompertz. El crecimiento en el medio de cultivo con 47.97% de proteína mostró superioridad al medio de cultivo con 35% de proteína; caracterizado por una mayor velocidad específica de crecimiento (μmáx) y menor tiempo de generación (TG) con valores de 0.86 h-1 y 0.80 horas, 0.81 h-1 y 0.86 horas respectivamente para cada medio de cultivo. Para la fase de adaptación (λ) y mayor crecimiento máximo (a) se obtuvieron: 0.97 horas y 1.60 para el medio con 45.97% de Proteína, así como 0.63 horas y 1.46 para el medio con 35% de proteína en la harina de soya respectivamente. La prueba de ANOVA demostró ",
