    "resumen": "This research's main contribution to minimize environmental pollution using fly ash are residues from the combustion of coal fluidized bed boilers, which damage the environment and health; and also contribute with new knowledge in the development of the construction industry. This research was conducted testing compressive strength of 36 specimens according to ASTM C-39, developed under the design of self-compacting concrete with replacement levels of portland cement by fly ash: 0%, 10%, 20% and 30% by weight of mixture, and wherein the dosages of superplasticizer used Viscocrete 1110 Sika brand of 1.1%, 1.40%, 1.75% and 2.12%, respectively, which improve the workability of the mixture, but without influencing the compressive strength. The design has a water / cement weight ratio of 0.44, with a base of 40 MPa. The samples were subjected to the test of resistance to compression at 14, 28 and 90 days of curing. The results at 14 and 28 days of curing, and fly ash replacement for portland cement 10%, exceeds the value of the compressive strength at 12% and 3% respectively, in the standard sample. However at 90 days of curing, the strength of the specimen with a replacement level of 1",
