    "area": "Logística y Cadena de Suministro",
    "resumen": "La presente investigación tiene por finalidad diseñar un Planeamiento Estratégico Financiero, con el fin de aumentar la rentabilidad de las empresas dedicadas a la distribución de productos veterinarios y afines, en ésta investigación he tomado como muestra a la empresa AVICO SAC, pues es una de las más representativas de la parte Norte del país. Para esto he aplicado el método descriptivo y analítico, a través de la recolección de datos, ya sea ésta en forma documentaria o proporcionada por la gerencia y el área de contabilidad. A la vez ésta investigación presenta un diseño no experimental, puesto que solo se procede a observar, describir y explicar la relación que existe entre el Planeamiento Estratégico Financiero y la Rentabilidad. Para la elaboración del Planeamiento Estratégico Financiero se ha analizado las fortalezas, oportunidades, debilidades y amenazas, con la que se enfrenta la empresa y en bases a ellas es que se ha propuesto un plan de acción en el cual se detalla el objetivo estratégico, la justificación, los objetivos específicos, las acciones a tomar, los responsables y los recursos a utilizar de ser el caso; junto con el plan de acción se ha realizado un Planeami",
