    "area": "Producción y Operaciones",
    "resumen": "Este estudio trata sobre las especias locales que contribuyen a la oferta turística gastronómica del distrito de Simbal, provincia de Trujillo, región La Libertad. Por tanto, identificamos a seis especias locales como el escabeche, pimentón, ají limo, culantro, cebolla y perejil que contribuyen a la diversificación culinaria en la preparación y presentación de sus platos típicos como cuy frito con revuelto de papa, pato guisado, pavita guisada, gallina guisada y cabrito; otorgándoles color, sabor y aroma. También apreciamos que los visitantes de fin de semana que prefieren concurrir a Simbal, generalmente son del distrito de Trujillo, en su mayoría de género femenino, profesionales de edades entre los 26 a 35 años, que han visitado el distrito de 5 veces a más debido a la cercanía que este tiene al distrito de Trujillo, por la variedad de platos típicos y por el precio de cada uno de ellos que es asequible para los profesionales que visitan el distrito. Los método científicos empleados son: Inductivo, Deductivo y Experimental; las técnicas de: el fichaje, la entrevista, la encuesta y la observación; y los instrumentos como: libreta de campo, guía de entrevista, cuestionario de encu",
