    "anio": 2013,
    "area": "Gestión de Proyectos",
    "resumen": "El presente trabajo estuvo orientado a identificar los antígenos en Líquido Seudocelómico de Ascaris suum, mediante la técnica de Electro-inmunotransferencia “Western Blot” utilizando IgY producidos en Gallus gallus. El Líquido Seudocelómico se obtuvo de ejemplares hembras que fueron extraídas directamente del intestino de cerdos naturalmente infectados y sacrificados en el Camal Municipal de El Porvenir; el cual se utilizó para inmunizar, junto con el adyuvante completo e incompleto de Freud, a un ejemplar de G. gallus; a fin de obtener IgY contenida en la yema de huevo. La IgY se usó en la Electro-inmunotransferencia para la determinación de los antígenos, de los cuales una parte fue tratada con Dithiothreitol (DTT) y la otra parte no fue tratada. En los antígenos tratados con DTT se encontró 12 bandas antigénicas, cuyos pesos moleculares fueron: 101.0, 94.9, 65.0, 61.1, 50.6, 45.0, 41.5, 34.6, 22.4, 16.3, 14.4 y 12.7-10.5 KDa; mientras que en los antígenos que no se trataron con DTT, se encontraron 15 bandas antigénicas cuyos pesos moleculares fueron: 101.0, 94.9, 65.0, 61.1, 50.6, 45.0, 41.9, 34.6, 27.0, 25.4, 21.5, 18.5, 16.3, 14.4 y 11.2 KDa. Estos resultados permiten conclui",
