    "resumen": "The industrial development at the world-wide level has experienced remarkable advances in the last years with respect to the Technology of Materials and it shows to the great meaning and importance to us that have metals specially the steel and their alloys using for the construction and manufacture of machineries, equipment, pieces and elements of machines._x000D_ At the present time the Physicists who work in the area of Materials have knowledge, that all the materials present/display own defects of their process of manufacture, like for example: vacancies, break-ups, pores, non-metallic inclusions and fissures; being the fissures the critical defects but, since these act like tension concentrators, arriving to propagate and to cause a catastrophic fracture, under applied conditions of load, inferior to those of design._x000D_ In the study of fault analysis this being developed a very important area that it is the Fractomecánico design attended by computer, which uses software specialized to simulate the Sub critical propagation of fissures as well as the catastrophic faults with a good approach with respect to the real data._x000D_ This work analyzes the approach in the determin",
