    "resumen": "La información, se ha vuelto un punto crítico dentro de las empresas, la_x000D_ necesidad de que esté disponible de manera continua, que se mantenga bien_x000D_ estructurada y que ésta esté disponible ante cualquier eventualidad, ha hecho_x000D_ que el concepto de alta disponibilidad, pase de ser una concepción teórica, a ser_x000D_ una necesidad para cualquier tipo de empresas desde las pequeñas empresas_x000D_ locales, hasta las grandes compañías transnacionales._x000D_ Los clúster, se han utilizado como alternativa a los grandes supercomputadores,_x000D_ a precios significativamente menores. Este tipo de tecnología tiene dos ramas de_x000D_ uso: crear supercomputadores o sistemas de alta disponibilidad._x000D_ En el diseño de clúster se definen tres tipos primarios sobre los cuales es posible_x000D_ mezclar para ajustarlos a las necesidades de la empresa. Estos modelos típicos_x000D_ son: balanceo de carga, alta disponibilidad y alto rendimiento._x000D_ Esta tecnología ha sido aplicada sobre diferentes arquitecturas de software, pero_x000D_ la parte del sistema operativo sobre el cual se ejecutan dependerá en alto grado_x000D_ de varios factores, como lo son, el costo de impleme",
