    "area": "Producción y Operaciones",
    "resumen": "Given the problems of low growth of electronic commerce in Peru compared to other countries in South America and the world, I proposed the idea of implementing an electronic commerce web site destinated to the importation of products, and their respective marketing._x000D_ The methodologies used are Brenda Kienan and the Rational Unified Process (RUP), which allowed the correct planning and project development._x000D_ This project is not designed for a particular type of item, the ideas in the project can be used for the importation and marketing of various types of products, from electronics to textiles. As a result of the Project you get an e-commerce web site, which will allow us to automate the process of marketing of imported products._x000D_ Electronic commerce is one of the most effective tools for importing and marketing of products, due to the large number of final customers and suppliers that will be accessible through the Internet, and low cost of the marketing process",
