    "resumen": "Se realizaron los ensayos para la evaluación de los parámetros de validación: Precisión, Exactitud, Linealidad, Rango y Especificidad, según el procedimiento operacional estandarizado del método analítico de valoración del principio activo Acido Acético en el Producto Thimolina Leonard solución por Titulación Potenciometrica Para realizar los ensayos se utilizó el Titulador Potenciometrico, balanza, cuya fecha de verificación y mantenimiento preventivo se encontraron vigentes al momento del uso. Se utilizó también un placebo preparado a las distintas concentraciones como blanco, así como también el producto THIMOLINA LEONARD SOLUCION con número de lote: 01179149. Se procedió tal cual el procedimiento analítico: Técnica FOR 0027 de Octubre del 2009. Una vez obtenido los gastos se efectuó el análisis estadístico de los datos correspondientes a cada parámetro. La evaluación de los parámetros de validación de la técnica de valoración del principio activo ACIDO ACETICO en el producto THIMOLINA LEONARD SOLUCION cumple con las especificaciones de los parámetros evaluados. Concluimos que nuestro método es específico, lineal, exacto y preciso en las condiciones descritas en el protocolo de ",
