    "anio": 2021,
    "area": "Logística y Cadena de Suministro",
    "resumen": "El presente trabajo de investigación se desarrolla en un operador minero, específicamente se evaluará la manera de incrementar la disponibilidad mecánica de los equipos de perforación que laboran en una mina subterránea. Se busca dar solución a la problemática de baja disponibilidad que presentan los equipos de perforación debido a las constantes paradas de equipos por fallas mecánicas, mediante el uso de herramientas de control, reportes de mantenimiento se ha podido identificar que una de las principales causas se debe a temas operativos, bajos estándares de calidad de los componentes hidráulicos y procedimientos ineficaces para la exigencia minera. Para dar una solución se busca implementar un sistema de abastecimiento que como consecuencia permita incrementar la disponibilidad mecánica (Reducir las paradas de equipos), establecer parámetros óptimos de calidad para los componentes hidráulicos, definir los procedimientos y reducir los costos logísticos. Se recurrirá a utilizar herramientas que permitan identificar los factores claves como el diagrama de Ishikawa, diagrama de Pareto para lograr cuantificar la situación actual, así mismo a través de un estudio de mercado se buscará",
