    "titulo": "Implementación de la metodología 5S en la gestión de  almacenaje de una distribuidora enfocada en minería para reducir el tiempo de despacho",
    "autor": "Jaramillo Luis, Hugo Francisco",
    "asesor": "Malca Chuquiruna, Raquel Beatriz",
    "anio": 2022,
    "area": "Logística y Cadena de Suministro",
    "resumen": "Este estudio se elabora sobre una empresa distribuidora, que se dedica al abastecimiento integral de las principales empresas y proyectos mineros del país, cuenta con 50 años operando en el mercado local. En línea a lo antes mencionado, se busca mejorar la gestión de almacenaje con la metodología 5S a fin de reducir el tiempo de despacho de cada pedido. Con la implementación de la metodología 5S, se busca reducir el tiempo que tarda el operario en encontrar los productos en el almacén, aumentar el espacio o área útil y disminuir el porcentaje de pedidos con error, todos estos problemas específicos repercuten a un tiempo de despacho elevado, lo cual perjudica la participación de la empresa en el mercado nacional. Para lograr esto se realiza una encuesta comparando el antes y después de implementada la metodología, con dicha información se plantea un plan de implementación que duró alrededor de 6 meses, que detalla todos los pasos que se siguen en la ejecución de cada “S”. Dentro de los resultados obtenidos, se reduce el tiempo que el operador tarda en encontrar los productos en 7.56 minutos, así como se reduce el porcentaje de pedidos con error en 37.23%, también se consigue increme",
