    "resumen": "Indica los beneficios de la metodología 5S mejorando el área de despacho. La insuficiencia de gestión en el área de despacho genera demora en los tiempos de entrega de las aves, bajo nivel de cumplimiento en los despachos e incremento laboral en los empleados. Para esta tesis se tiene como variable dependiente la mejora del despacho, se emplea indicadores de gestión logística, entre ellas las tres variables dependientes: nivel de cumplimiento, unidades despachadas por trabajador y entregas a tiempo. En la tesis se empleó el método cuantitativo, un tipo de investigación aplicada y el diseño que se utilizó fue experimental. La población se considera el despacho de aves en la empresa avícola y la muestra se determina por conveniencia y son los despachos de los meses agosto, setiembre y octubre del año 2018, y los meses febrero, marzo y abril del año 2019. Se tuvo como resultado final, la mejora del despacho en la empresa comercializadora de aves, según la prueba T student se tiene que p = 0,002 en otras palabras p ≤ 0.05, por tal motivo no se aprueba la hipótesis nula y se aprueba la hipótesis alternativa, que indica la mejora del despacho en una empresa comercializadora de aves en la",
