    "asesor": "Tinoco Gómez, Oscar Rafael",
    "anio": 2012,
    "area": "Gestión de Proyectos",
    "resumen": "El objetivo principal de este informe es resaltar el proceso de creación de estándares para la elaboración de planos de fabricación en el contexto del diseño de un prototipo digital como se muestra en el caso específico de una matriz de corte y embutido logrando de esta manera un incremento de la productividad, en función a la precisión, claridad y tiempos minimizados en la producción de los planos de fabricación. Mediante el software CAD Autodesk Inventor v. 2011 se diseñó el prototipo digital, una matriz de corte y embutido, se modeló todos los componentes de la herramienta de alta producción, se procedió a crear asimismo los subensambles y el ensamble general. Asimismo se realizó el modelado de los mismos componentes en Autocad realizándose un cuadro comparativo de tiempos de modelado entre ambos software CADs que confirmó al primero como una alternativa de software CAD para la creación de estándares, no obstante un tercer software CAD como Solidworks se presentaba como una alternativa de características muy similares a las de Autodesk Inventor, sin embargo, factores determinantes como costos de licencia, mantenimiento, soporte técnico, herramientas complementarias entre otros, ",
