    "resumen": "El presente trabajo, titulado Propuesta de un sistema de gestión de mantenimiento para maximizar los resultados de una empresa de fabricación de concreto en la ciudad de Arequipa, contempla una solución a las deficiencias evidenciadas en el diagnóstico situacional de la gestión del departamento de mantenimiento, a partir de una propuesta de sistema de gestión del proceso en mención para maximizar los resultados de la organización. El diagnóstico se realizó con una auditoría al proceso de gestión del departamento, el cual arrojó deficiencias en los criterios de evaluación establecidos en base al 100% de conformidad; por ejemplo, en el proceso estratégico de mantenimiento solo tiene el 34.3% de conformidad, organización general el 39.8%, compra y logística de repuestos y equipos el 37.5%, control de la actividad el 36.2%, etc. Con las conclusiones de la auditoria, se identificó las fortalezas, debilidades y acciones de mejora, las cuales soportan el sistema de gestión propuesto. La propuesta del sistema desarrolla el ciclo de Deming y en específico la etapa de planificación, identificando los factores que influyen significativamente en la gestión de esta etapa, como: la codificación ",
