    "resumen": "La logística dentro de una organización es sumamente importante para poder mantener un buen servicio y poder ser competitivos. Para ello, es necesario desarrollar una correcta gestión de stocks para poder tener una respuesta rápida hacia el cliente y se incremente el nivel de servicio. Cada empresa es única y manejan logísticas diferentes. Debido a eso, a la hora de desarrollar la política de inventarios, esta se debe adaptar perfectamente a las necesidades de la empresa para que pueda ser útil y es por ello que se tiene que desarrollar un buen análisis previo para evitar problemas a futuro. Las empresas siempre tienen que estar haciendo revisiones permanentes de sus procesos para que vayan mejorando ya que constantemente hay cambios internos y en el mercado que afectan de forma directa el funcionamiento organizacional. Además, tienen que tener claro que siempre hay problemas así sean pequeños que afectan en cierta medida dependiendo del grado el desempeño organizacional. En la presente tesis, se realizará un diagnóstico empleando diversas herramientas estadísticas y matemáticas para poder determinar de manera precisa el problema principal y las causas que lo generan. En base al re",
