    "resumen": "El presente trabajo de tesis tiene como objetivo principal proponer mejoras en la cadena de suministro la empresa de fabricación, comercialización y servicios en la sede Arequipa, con la finalidad de mejorar la satisfacción del cliente final tanto interno como externo generando una mejor rentabilidad, para lo cual se desarrollaron los siguientes capítulos. En el capítulo I se desarrollan el planteamiento del problema en el área de logística y almacén con sede Arequipa estableciendo objetivos, hipótesis, justificación y el método de recolección de información para el presente desarrollo. En el capítulo II se describen conceptos a la cadena de suministro y las propuestas a desarrollar de la metodóloga de las 5’s, indicadores logísticos, políticas de inventario y procedimientos en el área de logística y almacén que servirá de referencia para estas herramientas utilizadas. En el capítulo III se describe a la empresa recalcando los principales productos de venta, los servicios que brinda con su estructura organizacional permitiendo conocer a la empresa el desarrollo de sus actividades. En el capítulo IV se describe la situación actual del área de logística y almacenes en la empresa de F",
