    "resumen": "El presente proyecto de Tesis tiene como objetivo principal optimizar el desarrollo de los procedimientos que engloba la gestión de compras en la empresa ALNUSA S.A.C, lográndose mediante un exhaustivo análisis y evaluación de los resultados obtenidos en el diagnóstico situacional de la empresa. Para ello, se identificó los respectivos procesos y operaciones involucradas en la cadena de aprovisionamiento de suministros; con el propósito de reconocer todos aquellos factores críticos que dificultan el correcto funcionamiento del área de compras. Como se sabe, el proceso de gestión de compras involucra las actividades que abarcan desde la identificación de las necesidades de adquisición, la evaluación y negociación con los proveedores hasta el envío y transporte de la mercadería hasta las instalaciones de la empresa. Es importante, que el encargado del área de compras coordine con los diferentes proveedores, aspectos como: la forma de envío, el tiempo, la calidad, la cantidad, el precio y la garantía de los productos solicitados, de forma que no se susciten inconvenientes que impida a la empresa contar con los recursos necesarios en el momento indicado. Según lo desarrollado, se reali",
