    "area": "Logística y Cadena de Suministro",
    "resumen": "FEMACO S.R.L, es una empresa comercializadora de materiales de ferretería y construcción ubicada en la ciudad de Arequipa cuenta actualmente con 5 sucursales en toda la ciudad. El presente trabajo tiene como objetivo elaborar una propuesta de mejora para la optimización de la eficiencia del proceso de abastecimiento de aquellos productos que se compran a proveedores de la ciudad de Lima, de la empresa FEMACO S.R.L, mediante la aplicación de herramientas de lean manufacturing. mediante el mapa de flujo de valor, se identificaron siete problemas que afectan la eficiencia del proceso, asimismo con la aplicación del diagrama de Ishikawa y diagrama de Pareto se determinó que los principales problemas que afectan la eficiencia del proceso de abastecimiento de la empresa son: El tiempo de ciclo elevado que actualmente es de 17 días en promedio, el sobre stock en el 90% de sus productos y los movimientos y transportes innecesarios causados por el desorden del almacén principal y un layout deficiente de oficinas. Con el diseño del mapa de flujo futuro, se pretende reducir el tiempo de ciclo hasta en un 47%, asimismo se diseñó un nuevo layout de oficinas para reducir los traslados del person",
