    "resumen": "El presente trabajo tiene como objetivo general aplicar la propuesta de mejora en la gestión de producción, mantenimiento y logística de una planta procesadora de asfalto mediante el uso de herramientas de ingeniería industrial para el incremento de la rentabilidad, ya sea por deficiente ubicación de la procesadora de asfalto, deficiente plan de mantenimiento, deficiente balance de línea y deficiente gestión de repuestos. Planteado el problema, objetivos, hipótesis y variables, se hizo uso de la gestión de producción, mantenimiento y logística, en el cual se aplicaron herramientas como método de weber, capacitación, plan de mantenimiento preventivo, AMFE, criticidad, balance de línea, lead time y ABC, dichas propuestas de mejora se aplicaron a cada una de las causas raíz que presentaba la empresa mediante el diagrama Ishikawa, enfocándose en las que tienen mayor impacto en la rentabilidad de la empresa con un total de 4. Las propuestas de mejora se basaron en la implementación de herramientas de ingeniería industrial lo que permitió eliminar o disminuir actividades que no generaban valor alguno para la empresa ocasionando insatisfacción en el cliente. La pérdida antes de la propues",
