    "area": "Logística y Cadena de Suministro",
    "resumen": "El presente trabajo tuvo como objetivo general realizar la propuesta de mejora de procesos en las áreas de producción y logística de la empresa Camposol S.A. En primer lugar, se realizó un diagnóstico de la situación actual de la empresa en estudio. Se han seleccionado las áreas de producción y logística, ya que se diagnosticó que eran las de mayor criticidad en la empresa, debido a la ineficacia de los procesos y la generación de pérdidas en torno a ello. Una vez culminada la etapa de la identificación de los problemas, se procedió a redactar el diagnóstico de la empresa, en el cual se tomó en cuenta todas las evidencias para demostrar lo mencionado anteriormente. Asimismo, se realizaron cálculos para determinar el impacto económico que genera en la empresa estas problemáticas representado en pérdidas monetarias. La propuesta de implementación que se pretende diseñar contiene herramientas que permiten controlar los procesos que se utilizan para desarrollar las operaciones diarias. Estos tipos de metodologías se fundamentan en tener bajo control los estándares definidos, con el fin de garantizar que el proceso se realice en forma consistente y acorde a las expectativas del cliente.",
