    "area": "Logística y Cadena de Suministro",
    "resumen": "El presente trabajo tuvo como objetivo general Reducir los costos operacionales de la empresa Multiservicios Papillon S.A.C. mediante una propuesta de mejora en la gestión de ventas y operaciones de mantenimiento. En primer lugar se realizó un diagnóstico de la situación actual de la empresa de Transporte de carga pesada Multiservicios Papillon S.A.C. en las operaciones de transporte, mantenimiento, logística y ventas, puesto que se detectó que eran las de mayor problemática, ocasionando altos costos operativos. Después de concluir la primera etapa de identificación de problemas, se procedió a redactar el diagnóstico de la empresa de transporte, en el cual se tomó en cuenta la opinión de los trabajadores de cada área de estudio, y a su vez evidencias que demostraban lo mencionado anteriormente. Así mismo se realizó cálculos para determinar el impacto económico que genera la propuesta de mejora en la empresa, estas problemáticas representado en pérdidas monetarias. A su vez posteriormente se desarrollan propuestas planes de mejora para reducir dichos costos operativos actuales. Obteniéndose una comparación favorable para la empresa (costos con propuesta & costos actuales). Disminuye",
