    "area": "Logística y Cadena de Suministro",
    "resumen": "La presente tesis está enfocada en el análisis y evaluación del almacén de una empresa comercializadora de equipos industriales para aplicar una mejora. El objetivo es proponer metodologías que permitan administrar los almacenes de una manera más eficiente. En tal sentido, las alternativas seleccionadas buscan aumentar la productividad, a través de métodos de trabajo definidos y documentados en los procesos internos de recepción, movimiento y armado de productos, así como también se busca la disminución de los tiempos empelados en los ciclos de trabajo gracias a una mejor distribución del layout. Para lograr lo mencionado anteriormente, el presente trabajo hace uso de una serie de herramientas empleadas en el área de ingeniería industrial, tales como: diagrama de Ishikawa, factorial de Klein, tablas de enfrentamiento, metodología de las 5S, entre otros. Dichas herramientas nos permitirán hacer la evaluación, diagnóstico y brindar la solución que mejor se acomodé a las necesidades de la empresa en estudio. El trabajo consta de seis capítulos, los tres primeros hacen referencia a la descripción de la empresa y la evaluación del entorno interno y externo de la misma, para poder examin",
