    "titulo": "Propuesta de mejora del índice de productividad de la Empresa Fábrica de Alambres y Clavos MYL S.A.C. basado en la implantación de herramientas de lean manufacturing",
    "autor": "Muñoz Cerna, Cristhian Rubén",
