    "titulo": "Estudio de mejora en la línea de procesamiento de pota (Dosidicus gigas) congelada en una empresa",
    "autor": "Mendoza Trelles, Fatima Gabriela; Rivera Huaman, Fiorella Rocio",
    "asesor": "Meini Mendez, Oswaldo Guillermo Arturo",
    "anio": 2022,
    "area": "Gestión de Proyectos",
    "resumen": "El presente trabajo de investigación tiene como objetivo realizar un estudio de mejora en la línea de procesamiento de pota (Dosidicus gigas) congelada en una empresa de industria alimentaria ubicada en Lima, Perú; con la finalidad de mejorar la productividad de la línea. La pota es un molusco marino abundante en el mar peruano, concentrando “el 43% de las exportaciones pesqueras no tradicionales del país” (Lozada, 2019). En los últimos años, Perú se ha situado dentro de los 5 principales exportadores de pota a nivel mundial, consiguiendo una facturación de US$ 230 millones en el 2018 (Sistema Integrado de Información de Comercio Exterior, 2019). En La Empresa, la pota representa el 13.15% de las ventas totales de la Unidad de Procesos Industriales, por lo que el estudio se enfoca en mejorar la productividad de la línea, la cual al inicio de este estudio fue de 0.18 kg/S/. Se encontró que la principal causa de la baja productividad es la variabilidad de disponibilidad de materia prima, es decir, existen periodos en los cuales la pota es muy escasa. La solución propuesta fue implementar una nueva línea de procesamiento secundario de anillas y botones de pota precocida y congelada, y",
