    "area": "Gestión de Proyectos",
    "resumen": "El presente proyecto tiene como objetivo principal plantear y proponer una mejora en el proceso productivo de la compañía Lima Caucho S.A. mediante la ampliación de la capacidad de producción, enfocándose en el área de producción de rodantes. Para ello, se aplicaron herramientas de ingeniería como el estudio de tiempos para la determinación de los estándares de producción, elaborando una solución que traiga un beneficio económico a la compañía. Mediante la realización del diagnóstico se encontró que el porcentaje de cumplimiento del programa de producción para las llantas tipo OTR se encontraba en 83%, muy por debajo del 98% esperado por la compañía. Por medio del análisis Klein se encontró que los procesos con menor desempeño eran los procesos clave, en este caso, los procesos productivos. El balance de materia permitió encontrar el cuello de botella en el área de producción de rodantes, con una capacidad de producción equivalente a 450 llantas por semana. Se seleccionó como alternativa de mejora la importación e instalación de una tubuladora de segundo uso marca APEX, por cumplir mejor con los criterios de evaluación planteados. Por medio de esta mejora se logrará incrementar en ",
