    "id": "ulima-91794cb9-d2e",
    "titulo": "Propuesta de mejora para la reducción de costos de producción en proyectos de pilotes pre - excavados en la empresa PSV Constructores S.A.",
    "autor": "Peña Camerano, Natalia Alejandra; Ramírez Campos, Diana Alejandra",
    "asesor": "Echazú Brown, Julio Roberto",
    "anio": 2020,
    "area": "Logística y Cadena de Suministro",
    "resumen": "La globalización y la tendencia del ser humano a hacer un match entre la naturaleza y la infraestructura necesaria para la actividad industrial, integran la combinación más efectiva a la hora de generar mejoras en los cimientos de las grandes edificaciones y puentes del mundo. Entre más altura tenga un edificio o entre más distancia tengan los apoyos de un puente, mayores serán las exigencias de las cimentaciones que los soportan. Las cimentaciones profundas realizadas con pilotes perforados se han convertido en la solución más práctica y económica al momento de satisfacer los requerimientos de las resistencias dependientes de las superestructuras. Estos pilotes varían en longitud y diámetro según las demandas del proyecto, y para su proceso de ejecución se utilizan accesorios de perforación y maquinaria pesada que permite, en síntesis, realizar un agujero en el suelo, similar a la acción de perforar una pared de una casa con un taladro eléctrico de mano. Las herramientas de perforación utilizan unos consumibles conocidos como “picas”, las cuales constituyen el elemento fusible en el tren de producción, dado que presentan un costo relativamente bajo comparado con el costo de la máq",
