    "area": "Logística y Cadena de Suministro",
    "resumen": "La investigación evalúa el efecto de implementar 5S para elevar la productividad del almacén de insumos de Competec S.A.C., empresa metalmecánica que atiende a alimentos, bebidas, minería, hidroeléctrico e industria. Parte de una línea base y un diagnóstico logístico que evidencian desorden, tiempos muertos, errores de picking y obsolescencia; la intervención integra clasificación, orden, limpieza, estandarización y disciplina, apoyadas por gestión visual, capacitación y auditorías por capas, y se mide con cumplimiento a tiempo, exactitud de picking, tiempo de atención, disponibilidad y un OEE intralogístico. El capítulo inicial presenta a la compañía (MYPE en Lurigancho), su organigrama, visión, misión, política de calidad y portafolio ligado a mecanizado CNC, compresores y mantenimiento, destacando prácticas de seguridad, ambiente y responsabilidad social. El segundo capítulo caracteriza el deterioro 2016–2022 y lo explica con un Ishikawa que reúne causas en procesos, sistemas, datos, personas, metodología y medición; formula el problema y objetivos, y define alcances y limitaciones centrados en el almacén. El tercero revisa antecedentes y bases teóricas de 5S, su integración con",
