    "area": "Logística y Cadena de Suministro",
    "resumen": "El sector hidrocarburos en el país de Perú ha venido decreciendo en los últimos años, lo cual, ha llevado al sector a una situación complicada donde la inversión y la producción se han visto afectadas; en el caso particular del petróleo, la caída ha sido constante desde el año 2015, mientras que la producción de gas viene creciendo en el país y está representando una gran oportunidad para el mismo y para la Empresa INMAC PERÚ S.A.C. Los beneficios que ofrece el sector hidrocarburos al país son múltiples; pero es necesario resaltar que este sector aporta 10 veces mayores regalías frente al sector minero, representa el 64% de las fuentes de energía que consumimos como país y principalmente representa el 100% del mercado de construcción para el sector hidrocarburos. Considerando la importancia del sector hidrocarburos para el país y la oportunidad de crecimiento del sector gas para INMAC PERÚ S.A.C., originando que se busquen alternativas que logren incrementar la calidad de los productos, así como disminuir el costo de los mismos. Teniendo en consideración lo descrito, el presente trabajo tiene como propósito primordial conocer que métodos de trabajo deben implementarse para la mejor",
