    "area": "Logística y Cadena de Suministro",
    "resumen": "La presente investigación tiene como objetivo mejorar la eficiencia de la gestión de abastecimiento y fortalecer el control de la seguridad ocupacional mediante la aplicación de herramientas de Lean Manufacturing durante la ejecución de proyectos eléctricos en la empresa “Servicios y Contratistas Generales M&E S.A.C”., ubicada en la región La Libertad en el 2024. El estudio surge a partir del diagnóstico de los procesos logísticos y operativos de la organización, donde se identificaron deficiencias relacionadas con la falta de estandarización en el abastecimiento de materiales, errores en los despachos y debilidades en el control del uso de Equipos de Protección Personal y en la aplicación del Análisis Seguro de Trabajo. Para el desarrollo de la investigación se empleó un enfoque aplicado, utilizando herramientas de análisis como el diagrama de Ishikawa, el análisis de Pareto y la matriz de decisión multicriterio AHP para identificar las causas críticas del problema y seleccionar la alternativa de mejora más adecuada. A partir de este análisis se diseñó un modelo de mejora basado en herramientas Lean Manufacturing, tales como estandarización de procesos, Poka- Yoke administrativo, ",
