    "resumen": "El presente trabajo aborda un proyecto de transformación digital de los controles de acceso que se aplican a la carga de un almacén aduanero, dicha propuesta surge debido a que se generan colas internas y externas por los transportistas de carga para ingresar y salir de las instalaciones de la empresa ya que el transportista debe pasar por varios puntos de control en los que se realizan registros manuales de sus datos y del servicio que están brindando a los clientes; adicionalmente, ante una necesidad de recupero de información, sea por una auditoría o alguna investigación del estado, toma mucho tiempo la búsqueda para demostrar el control de todos los movimientos que realizan los transportistas una vez que ingresan a las instalaciones. Para el desarrollo del proyecto se definieron 4 etapas: 1. Modelamiento AS IS. 2. Medición y Análisis. 3. Modelamiento TO BE. 4. Implementación de la solución La primera etapa, modelamiento AS IS, consiste en identificar el proceso y los controles establecidos por la organización; la segunda etapa, Medición y Análisis, consiste en hacer mediciones en campo, elaborar reportes estadísticos de movimientos y tiempos para analizarlos y determinar los pu",
