    "id": "uni-9d1bb763-022",
    "titulo": "Diseño de un sistema de costeo por procesos para mejorar el control de costos en la planta de beneficio de una empresa minera aurífera ubicada en una región del Perú",
    "autor": "Angulo Vera, Roger David",
