    "anio": 2025,
    "area": "Producción y Operaciones",
    "resumen": "La presente investigación plantea el diseño de un sistema de costeo por procesos como herramienta para la mejora del control de costos en la planta de beneficio de una empresa minera ubicada en una región del Perú. El estudio se realizó en una empresa minera aurífera a cielo abierto ubicada en una región del país, para ello se analizará el proceso de producción de la barra doré y de esta manera obtener datos de los distintos procesos con los que cuenta la planta de beneficio y poder finalmente diseñar el sistema de costeo por procesos teniendo en cuenta los diversos recursos que están involucrados en cada proceso. Con el diseño de un sistema de costeo por proceso, se espera obtener un mejor seguimiento de los costos en la planta de beneficio de una empresa minera, contar con un modelo para la determinación de costos unitarios según procesos en la planta e información para la toma de decisiones.",
