    "resumen": "Para poder dar solución al problema de productividad de la comunidad campesina analizada, se propuso desarrollar una investigación aplicada, objetiva y de tipo descriptiva; para la cual se realizó una recopilación de la información existente y bibliografía relacionada con la planificación estratégica y mejora de la productividad. La causa más importante de las variaciones en la productividad se debió, en gran medida, a problemas en la organización y gestión, así como las técnicas de limpieza, habitual en los criaderos de cuyes, lo que también derivaba en el deterioro de la salud y cuidado de estos animales; incurriendo en bajas ventas y obstáculos para asegurar la producción y gestión comercial. La solución que se propuso está basada en la correcta aplicación de las tres etapas del planeamiento estratégico que incluyen formulación, implementación y evaluación. Para proporcionar una estrategia generalizada hacia el incremento de la productividad. Los hallazgos de la investigación actual están basados en el mejoramiento significativo de la productividad, lo cual tuvo un incremento del 48.8% anual luego de implementar el planeamiento estratégico.",
